window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q08"]=window.__LIBQ["pham-nhan-tu-tien"]["q08"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q08"]["cotTruyen"]=[{"chuong":1262,"tieuDe":"Bến Bờ Xa Lạ","tomTat":"Hàn Lập nằm bất động suốt ba tháng giữa một sa mạc khô nóng có bảy thiên thể luân phiên tạo thành ngày và đêm, nhưng chưa thể xác định nơi này có phải Linh Giới hay không. Trong hành trình vượt qua không gian tiết điểm, không gian phong bạo đã phá hủy phần lớn bảo vật hộ thân, chôn vùi Bát Linh Xích và tách hắn khỏi Băng Phượng. Cấm chế Băng Phượng từng hạ trên người hắn phát tác, phá hoại kinh mạch nhanh hơn khả năng chữa trị của Mộc Sinh Châu, buộc hắn phải tự tán Nguyên Anh thành Đại Tinh Nguyên để bảo toàn thân thể. Biện pháp này giúp hắn sống sót nhưng khiến hắn không còn pháp lực, không thể hấp thu linh lực hoặc vận dụng thần niệm trong hơn một trăm năm. Khi một đàn quái điểu đầu ưng lao xuống, Hàn Lập dùng hơi thở bắn cát đá làm trọng thương vài con, khiến những con còn lại quay sang ăn thịt đồng loại rồi bỏ đi. Sau đó, một con chim đỏ phát tiếng báo tin và dẫn đoàn kỵ sĩ cưỡi thanh sắc cự lang tới chỗ hắn. Do bất đồng ngôn ngữ, đôi bên không thể giao tiếp, và chương kết thúc khi một thanh niên bản địa dùng Viên Bàn lóe sáng về phía Hàn Lập."},{"chuong":1263,"tieuDe":"Huyết Chú Văn Và Linh Cụ","tomTat":"Một thanh niên thuộc đội kỵ sĩ dùng Viên Bàn kiểm tra Hàn Lập rồi kinh hoảng báo cho những người phía sau, khiến Trương Khuê tiến lên tra hỏi. Do hai bên không hiểu ngôn ngữ của nhau, Trương Khuê kích hoạt một viên châu vàng và đưa nó vào cơ thể Hàn Lập, giúp hắn nhanh chóng tiếp thu tiếng nói bản địa. Hàn Lập biết mình đang ở vùng sâu Thanh La Sa Mạc và đồng ý phục vụ Thiên Đông Thương Hào hai mươi năm để được đưa rời khỏi nơi nguy hiểm này. Khi biết thỏa thuận phải lập bằng Huyết Chú Văn Thư, hắn âm thầm nhận định cấm chế chỉ đủ ràng buộc tu sĩ Trúc Cơ và khó uy hiếp thân thể mình. Tiểu Thất dùng chủy thủ lấy máu nhưng không thể để lại vết xước trên cổ tay Hàn Lập, khiến toàn bộ đội kỵ sĩ kinh ngạc. Hàn Lập công khai đã luyện Kim Cương Quyết tới tầng thứ ba, qua đó khiến Trương Khuê coi hắn là nhân lực quý giá có thể đối kháng yêu thú cấp thấp. Trương Khuê sau đó giao Kim Oánh Kiếm cho Tiểu Thất, còn Hàn Lập quan sát linh thạch gắn ở chuôi kiếm cùng bao tay da thú và chính thức xác nhận mình đã tới Linh giới."},{"chuong":1264,"tieuDe":"Thiên Đông Thương Hào","tomTat":"Trương Khuê dùng bao tay khu động Kim Oánh Kiếm, khiến Hàn Lập nhận ra phàm nhân Linh Giới có thể sử dụng Linh Cụ để uy hiếp tu sĩ cấp thấp. Do thể phách quá mạnh, Hàn Lập phải kiềm chế Kim Cương Quyết mới để lưỡi kiếm rạch cổ tay lấy máu. Sau khi chấp thuận Huyết Chú Văn Thư, hắn chính thức gia nhập Thiên Đông Thương Hào và được bố trí lên cự quy dưỡng sức. Trong thùng xe, Hàn Lập nghe các thiếu nữ tiết lộ đoàn thương hào đang vận chuyển một lô hàng liên quan tới an nguy của An Viễn Thành. Hà phu nhân đã đi trước để xử lý công việc và đón Ngũ thiếu gia, người có linh căn từng được tu tiên giả nhận làm môn hạ. Cuối chương, Nam Kỳ Tử được Trương Khuê mời tới khám cho Hàn Lập, còn Phù lão bất ngờ xuất hiện cùng ông."},{"chuong":1265,"tieuDe":"Nam Kỳ Tử Và Phù Lão","tomTat":"Nam Kỳ Tử cùng Phù lão tới thùng xe để khám thương cho Hàn Lập sau khi biết hắn đã luyện Kim Cương Quyết tới tầng thứ ba. Nam Kỳ Tử dùng kính đồng xác định hơn phân nửa kinh mạch của Hàn Lập đã vỡ nát nhưng thương thế vẫn còn khả năng chữa khỏi, rồi chuẩn bị Thanh Tâm Phù giúp hắn giảm đau. Trong lúc quan sát pháp khí trữ vật của đạo sĩ, Hàn Lập nhớ lại việc mình đã chôn phần lớn trọng bảo và túi linh thú trong sa mạc, đồng thời giao Phệ Kim Trùng, Lục Dực Sương Công và Đề Hồn Thú canh giữ. Phù lão thi triển Huyền Thiên Kim Châm thuật, giúp Hàn Lập tạm thời ngồi dậy, cử động tay chân và đi lại, nhưng cảnh báo hắn không được sử dụng khí lực. Sau khi Nam Kỳ Tử kích hoạt phù triện, hai người rời khỏi thùng xe. Liễu nhi liền hỏi về Kim Cương Quyết tầng ba, còn Hàn Lập chỉ đáp rằng mình may mắn luyện thành để tiếp tục che giấu thực lực và lai lịch."},{"chuong":1266,"tieuDe":"Sa Trùng Thú","tomTat":"Liễu nhi giới thiệu cho Hàn Lập biết Thiên Đông Thương Hào là một trong ba hiệu buôn lớn nhất Thiên Nguyên Cảnh, có chi nhánh tại hơn một trăm thành thị và đặt tổng bộ ở Thiên Nguyên Thánh Thành. Xa đội đột ngột dừng lại khi Xích Linh tước phát hiện đàn Sa Trùng Thú có yêu trùng mở linh trí và vài cá thể biến dị đang theo dõi, sau đó tăng tốc hình thành vòng vây. Nhóm tu sĩ Cẩu Lũ sơn của Nam Kỳ Tử từ chối trợ chiến vì trùng thú chưa chủ động công kích họ và truyền thừa khu trùng của môn phái khiến việc đối phó yêu trùng có nhiều điều bất tiện. Liễu nhi quyết định sử dụng hổ thú do phu nhân giao, dùng thủ trạc cùng lệnh bài giải trừ tấm lụa đen quanh lồng bạc rồi lấy huyết quang áp chế con thú. Quan sát quá trình này, Hàn Lập nhận ra Linh cụ có thể giúp phàm nhân kích phát linh lực trong linh thạch nhưng sẽ mất tác dụng khi linh lực cạn. Khi đàn trùng thú áp sát, Trương Khuê ra lệnh gom cự quy và hàng hóa vào trung tâm, tập hợp vệ sĩ cùng cự lang kỵ sĩ để lập thế chỉ thủ không công. Dù Vương bá khuyên trú trong thùng xe thiết mộc, Hàn Lập vẫn ở lại bên ngoài vì muốn tận mắt quan sát hình dạng Sa Trùng Thú."},{"chuong":1267,"tieuDe":"Cự Trùng Đột Kích","tomTat":"Khi cự quy chở Hàn Lập trở lại đội ngũ, quy xa đội lập tuyến phòng ngự bằng hơn ba mươi mai cự quy, còn các kỵ sĩ tập hợp dưới sự chỉ huy của Trương Khuê. Trương Khuê nuốt một viên bích lục đan hoàn, vận công biến đổi thân thể rồi dẫn quân lao vào bụi vàng nghênh chiến. Hàng trăm Sa Trùng Thú tràn ra, dựa vào thân thể dày chắc và số lượng đông đảo để xuyên thủng phòng tuyến, khiến hơn hai mươi thủ vệ chết hoặc bị thương. Hàn Lập vẫn đứng ngoài quan sát vì thân thể luyện Minh Vương Quyết tầng thứ tư và Diệt Tiên Châu đủ bảo đảm an toàn, trong khi Nam Kỳ Tử cùng những tu sĩ khác cũng không chịu xuất thủ. Trước tình thế nguy cấp, Hương nhi và hai thiếu nữ đồng hành triển khai Tiểu Hồi Xuân Trận, giúp các thủ vệ khôi phục tinh thần và tạm thời giành lại ưu thế. Tuy nhiên, Hàn Lập nhận ra trận pháp này chỉ là phiên bản đơn giản hóa của Tinh Nguyên Trận tại Nhân Giới, dùng việc tiêu hao tinh nguyên để đổi lấy sức mạnh nhất thời. Mỗi thủ vệ được gia trì vì thế đã âm thầm mất khoảng hai đến ba năm thọ nguyên."},{"chuong":1268,"tieuDe":"Xà Yêu","tomTat":"Một xà yêu mặt người bất ngờ tập kích ba thiếu nữ đang duy trì Tiểu Hồi Xuân Trận, đánh Thuyên Nhi khỏi quang hà rồi dùng cốt mâu truy sát nàng. Hàn Lập dù cơ thể khó cử động vẫn liên tiếp ném đá, cứu Thuyên Nhi và buộc yêu thú phải tự bảo vệ. Nam Kỳ Tử phóng tiểu kiếm trong suốt khiến xà yêu dùng độn thuật đào thoát, nhưng trước khi đi nó ném cốt mâu đánh Hàn Lập bay vào xe hàng. Kim Cương Quyết tầng ba giúp thân thể Hàn Lập không bị pháp khí cấp thấp làm tổn thương, song việc gắng sức khiến kinh mạch của hắn nặng thêm. Tiểu Hồi Xuân Trận sau cuộc tập kích đã cạn sạch uy năng và không thể tái kích hoạt. Đội kỵ sĩ trở về sau khi tiêu diệt yêu trùng chỉ huy, nhưng lực lượng giảm từ khoảng năm mươi xuống chỉ còn hơn ba mươi người. Biết Hàn Lập cứu Thuyên Nhi, Trương Khuê công khai cảm kích và người của thương hội trở nên thân thiện hơn với hắn. Sau khi chỉnh đốn, đoàn xe rời Thanh La Sa Mạc và tiến vào thảo nguyên, nơi sự yên tĩnh bất thường khiến bốn thiếu nữ đều lộ vẻ sợ hãi."},{"chuong":1269,"tieuDe":"Thành An Viễn","tomTat":"Trong thời gian đồng hành, Hàn Lập hỏi các thiếu nữ về Thiên Đông Thương Hào và biết Phương phu nhân đang chủ trì cơ nghiệp sau biến cố của gia đình người con trưởng. Bà đã đi trước đến Thành An Viễn vì nhận được lời nhắn cầu trợ giúp từ người con có Linh Căn đang tu tiên tại đây, còn Hàn Lập lưu ý bí ẩn về vị gia chủ chỉ là phàm nhân nhưng vẫn nắm giữ cơ nghiệp lớn. Xa đội vượt qua thảo nguyên Lang Thú sau thời gian dài cảnh giới nghiêm ngặt, đồng thời nghe phỏng đoán Thành An Viễn có thể sắp đối mặt đại thú triều ngàn năm một lần. Trong lúc đó, nhờ Mộc Sinh Châu và Kim Cương Quyết, kinh mạch Hàn Lập đã hồi phục hơn phân nửa, còn chiến lực hiện tại được hắn đánh giá đủ áp đảo tu sĩ Trúc Cơ hậu kỳ. Đoàn người sau đó tới Thành An Viễn, một thạch thành có tường cao, thành lâu dày đặc, hoa văn bí ẩn và những cự nỏ đủ sức đe dọa tu sĩ Trúc Cơ. Quân thủ thành kiểm tra lệnh bài của Trương Khuê rồi mở cửa, nhưng vẫn yêu cầu tu tiên giả khám xét xa đội để ngăn yêu thú trà trộn. Chương kết thúc khi Lý tiên sinh và Hoàng đại sư được gọi ra thực hiện việc kiểm tra."},{"chuong":1270,"tieuDe":"Tạm Biệt","tomTat":"Theo lệnh Thành Chủ, một nho sinh áo trắng và một tăng nhân áo cà sa xanh dùng pháp khí kiểm tra toàn bộ đoàn Thiên Đông Thương Hào trước khi Triệu Thống lĩnh cho họ tiến vào An Viễn Thành. Bên trong thành, dân chúng từ các thôn xóm bên ngoài đã đổ về tránh thú triều, khiến đường phố đông nghẹt và bầu không khí phòng bị trở nên căng thẳng. Đoàn xe giao toàn bộ hàng hóa tại kho rồi chuẩn bị tới khách điếm ở thành tây hội hợp với Phương phu nhân. Hàn Lập xin tạm rời đoàn để tự xem xét trong thành, còn Trương Bản cùng Nam Kỳ Tử bàn về lai lịch khó dò, Huyết Chú Văn Thư và tiềm năng luyện Kim Võng Quyết của hắn. Nam Kỳ Tử cùng các tu sĩ Hưởng Lâu Sơn hoàn thành nhiệm vụ hộ tống và cáo từ. Trong lúc đi quanh thành, Hàn Lập nhận ra linh khí nơi đây vượt xa Nhân giới nhưng bản thân không thể hấp thu vì đã tán Nguyên Anh và còn chịu cấm chế của Băng Phượng. Cuối cùng hắn bước vào một cửa hàng binh khí, nghe giới thiệu về Kim Bối Cửu Hoàn Đao rồi dừng lại trước một thanh đại hoàn đao đen nhánh có vẻ rất nặng."},{"chuong":1271,"tieuDe":"Địa Giao Cân","tomTat":"Hàn Lập tới cửa hàng binh khí tìm một loại vũ khí dạng dây, nhưng lần lượt từ chối Nguyệt Hồ Kiếm và Cầu Long Tác vì chúng không phù hợp với yêu cầu của hắn. Hán tử họ Bảo và Tân hiền đệ nhận ra nhu cầu ấy nên dẫn hắn tới một hẻm vắng, đưa ra sợi gân lấy từ con Địa Giao mà nhóm luyện thể sĩ của họ từng săn giết. Sau khi kiểm tra độ bền chắc và khả năng co giãn của Địa Giao Cân, Hàn Lập mua món vật liệu với giá ba mươi khối linh thạch cấp thấp, thanh toán bằng một khối linh thạch trung giai rồi nhận lại tiền thừa. Hắn quấn sợi gân thành vòng quanh cổ tay, giấu dưới tay áo và rời đi. Tân hiền đệ nảy ý định tập kích người mua nhưng bị hán tử họ Bảo ngăn lại vì thực lực và lai lịch của Hàn Lập đều khó dò. Cuộc trò chuyện sau đó hé lộ hiệp nghị giữa Tam Hoàng và Thất Yêu Vương, theo đó tu sĩ Kết Đan và yêu thú cao hơn cấp năm đều bị hạn chế tham gia thú triều, khiến các luyện thể sĩ trở thành lực lượng phòng thủ thiết yếu của An Viễn Thành."},{"chuong":1272,"tieuDe":"Thú Triều","tomTat":"Sau khi tách khỏi đoàn người Thiên Đông Thương Hào, Hàn Lập vào một thư điếm tại An Viễn Thành mua điển tịch và bản đồ rồi đến tửu lâu đọc. Qua sách vở, hắn biết lãnh thổ nhân tộc gồm Thiên Nguyên Cảnh, Huyền Vũ Cảnh và Thiên Linh Cảnh, trong khi Yêu Tộc chiếm giữ Thất Yêu Chi Địa. Ba chủ thành của nhân tộc được xây tại Thiên Nguyên Thánh Sơn, trên lưng cự quy Tham linh và trên Kình Thiên Linh Thụ, đồng thời là những trận nhãn quan trọng của siêu đại pháp trận bảo hộ hai tộc. Pháp trận có nguồn gốc từ cổ tiên trận, gồm mười trận nhãn và đặc biệt ngăn cản những sinh linh có thân thể quá cường đại, nhưng Hàn Lập vẫn chưa hiểu cơ chế đưa người phi thăng vào đúng khu vực được bảo vệ. Hắn cũng biết hiệp nghị nhân–yêu hạn chế cường giả tàn sát quần thể cấp thấp và cấm tu sĩ cao giai tham gia phòng thủ thành thị khi thú triều xảy ra. Việc yêu thú sinh sản quá nhanh khiến chúng định kỳ tấn công thành trì, còn những trận chiến sinh tử này lại giúp người tu luyện cấp thấp có cơ hội phá bình cảnh nên cao tầng nhân tộc ngầm chấp nhận. Từ vị trí gần thảo nguyên và bầu không khí khẩn trương của An Viễn Thành, Hàn Lập kết luận nơi đây sắp gặp thú triều, rất có thể là lang triều hoặc thậm chí đại thú triều."},{"chuong":1273,"tieuDe":"Thiên Kiếp Chi Nguy","tomTat":"Hàn Lập nhận ra cảnh giới Hóa Thần vẫn còn khiến hắn có thể phải đối diện tiểu thiên kiếp, trong khi pháp lực đã mất, bảo vật không thể sử dụng và Kim Cương Quyết mới đạt tầng bốn. Hắn loại bỏ phương án tìm Băng Phượng giữa Linh giới rộng lớn cũng như việc cầu viện cao giai tu sĩ vì sợ các bí mật trên người bị phát hiện. Sau khi cân nhắc nền tảng thân thể đã được nhiều lần cường hóa, hắn quyết định luyện Kim Cương Quyết tới tầng bảy đại thành để cưỡng ép phá cấm chế, khôi phục khả năng hấp thu linh lực và ngưng tụ lại Nguyên Anh. Vì các tầng cuối cần thông qua tranh đấu, Hàn Lập chọn tạm thời ở lại Thiên Đông Thương Hào, đồng thời biết rằng Huyết Chú Văn Thư đã bị tinh nguyên trong cơ thể luyện hóa nên không thể trói buộc mình. Hắn hủy quyển điển tịch đã đọc, giao Địa Giao Cân cùng vật liệu và linh thạch cho một thợ rèn rồi thuê xe trở về Như Vân Khách Điếm. Tại Tây viện, La Tiểu Thất thử nắm tay Hàn Lập nhưng bị né tránh dễ dàng, qua đó nhận ra thân thủ hai bên chênh lệch. La Tiểu Thất sau đó dẫn Hàn Lập tới gặp Phương phu nhân, nơi hai đại hán canh tiểu viện lập tức dùng ánh mắt lạnh lẽo dò xét họ."},{"chuong":1274,"tieuDe":"Kim Ngọc Tông","tomTat":"Theo sự sắp đặt của Phương phu nhân, hai thiếp thân thị vệ thử sức Hàn Lập ngay ngoài sân, nhưng hắn dùng lực phản chấn quăng một người bay đi và khiến người còn lại phải lùi liên tiếp khi cứu đồng bạn. Cự lực của Hàn Lập không chỉ đến từ Kim Cương Quyết tầng thứ tư mà còn được bồi đắp bởi Long Lân quả và quá trình tịnh tu Thối Cốt Quyết suốt mấy trăm năm. Khi gặp Phương phu nhân, Phan Thanh cùng ba đệ tử Kim Ngọc Tông, hắn che giấu lai lịch và thuận thế nhận mình có thần lực trời sinh. Phương phu nhân cho biết Kim Ngọc Tông cùng hơn mười tiểu tông môn đã đưa đệ tử tới An Viễn Thành để chống thú triều và tìm cơ hội đột phá bình cảnh. Vì đội hộ vệ Thiên Đông Thương Hào phải chịu sự điều động của thành, bà bổ nhiệm Hàn Lập làm phó thủ của Trương Khuê và hắn đồng ý. Sau khi Hàn Lập rời đi, Phương phu nhân đánh giá hắn có tiềm lực sánh với Hỏa Lão nên muốn thay Trương Khuê hoặc Liễu gia huynh đệ vào kế hoạch bí mật vốn dành cho hắn."},{"chuong":1275,"tieuDe":"Thanh Lang, Xích Mãng, Báo Cầm","tomTat":"Tần Kỳ Quyền thuyết phục Phương phu nhân đưa Hàn Lập vào kế hoạch đoạt một vật do yêu thú canh giữ, lấy triển vọng kết đan của Phan Thanh làm lý do và lợi dụng thời cơ thú triều. Không biết mình đang bị tính kế, Hàn Lập nhận chức phó đội hộ vệ của Thiên Đông Thương Hào, dùng một phần thần lực áp đảo những người bất phục rồi dành thời gian nghiên cứu tầng năm Kim Cương Quyết và bí mật rời khách điếm nửa ngày. Đến ngày thứ bảy, chuông báo thú triều vang khắp An Viễn Thành, vệ binh truyền lệnh giới nghiêm còn Trương Khuê ổn định đội hộ vệ và đưa Hàn Lập lên tường thành quan sát. Trinh sát xác nhận ba đợt thú gồm Thanh Lang từ Hắc Lang Sơn Mạch, Xích Mãng từ Phỉ Thúy Thảo Nguyên và một lực lượng lớn phi cầm. Thành chủ An Viễn Thành tập trung tu sĩ đối phó phi cầm, giao yêu thú mặt đất cho luyện thể sĩ cùng vệ binh và chỉnh đốn quân mới chiêu mộ để luân phiên tác chiến. Ngoài thành, vô số Thanh Lang phủ kín vùng đất kéo dài ngoài tầm mắt; khi Trương Khuê nhắc đến mức nguy hiểm của Ngân Lang, Hàn Lập thoáng biến sắc."},{"chuong":1276,"tieuDe":"Cuồng Thú Chi Triều Phần 1","tomTat":"Hàn Lập nghe chuyện về Ngân Lang và liên tưởng tới bản thể Ngân Sắc Cự Lang cùng xuất thân Ngân Nguyệt Lang Tộc của Ngân Nguyệt, nhưng tạm gác nghi vấn vì chưa có căn cứ. Trương Khuê giải thích rằng thú triều đặc biệt nguy hiểm do có yêu thú thủ lĩnh đã mở linh trí và hàng nghìn cá thể biến dị, trong khi An Viễn Thành từng chịu tổn thất nặng và còn thiếu lực lượng phòng không. Hai người lần lượt quan sát biển Thanh Lang và đàn Xích Mãng đông đảo, nhận ra các đàn thú dường như đang phối hợp để chờ thời điểm tổng công kích. Trở về khách điếm, Trương Khuê dẫn hơn hai trăm thủ vệ Thiên Đông Thương Hào tới quảng trường tập kết, nơi hàng vạn người đang được chỉnh biên và phân phát trang bị. Những người có tọa kỵ được lựa chọn làm chỉ huy kỵ binh, còn các tu sĩ phụ trách kiểm tra và cảnh giới trên không. Sau một tiếng sói tru, hàng vạn Thanh Lang đồng loạt đứng dậy, phía Xích Mãng cũng vang tiếng hưởng ứng và bắt đầu tiến về thành. Chuông báo động nổi lên, quân đội khẩn cấp kéo lên tường thành, còn người vận hành cự cung vào vị trí chuẩn bị giao chiến."},{"chuong":1277,"tieuDe":"Cuồng Thú Chi Triều Phần 2","tomTat":"Lực lượng tư nhân và các luyện thể tu sĩ được chỉnh biên để hỗ trợ quân chính quy thủ thành, trong đó Hàn Lập cùng hai trăm hộ vệ Thiên Đông Thương Hào nhận nhiệm vụ bảo vệ một đoạn tường thành. Hàn Lập và Đỗ Khiếu theo sát viên quan quân chỉ huy khi đàn thanh lang đông vô tận áp sát, xen lẫn những cự lang biến dị có linh tính. Quân thủ thành dùng hàng trăm xe bắn đá phóng hỏa cầu, tiêu diệt gần hai vạn thanh lang trước khi nguồn đạn hỏa công ngừng xuất hiện. Đàn sói bị kích động liền tổng công kích, trèo lên vách đá và giao chiến với quân phòng thủ suốt từ giữa trưa tới chiều tối, khiến binh sĩ tổn thất khoảng một phần ba và Thiên Đông Thương Hào mất hơn hai mươi hộ vệ. Khi trời tối, các cự lang biến dị cao lớn bất ngờ leo lên thành, gần như bỏ qua cung nỏ thông thường và tàn sát binh sĩ, buộc các luyện thể tu sĩ phải xuất chiến. Hai cự lang sau đó dùng kế dương đông kích tây để tập kích viên chỉ huy, còn Đỗ Khiếu vung lang nha bổng đánh chặn ngay trước khi chương kết thúc."},{"chuong":1278,"tieuDe":"Cuồng Thú Chi Triều Phần 3","tomTat":"Con yêu lang phá tan kiếm ảnh hộ thân của quan quân họ Tiếu, nhưng Hàn Lập kịp thời can thiệp và dùng một quyền kim quang đánh nát trảo mang. Đỗ Khiếu cùng các luyện thể sĩ của Thiên Đông Thương Hào tạo thế bao vây, song yêu lang dùng hư chiêu thoát về đàn sói, còn Hàn Lập không truy sát. Nhiều đoạn thành lân cận đồng thời bị hàng nghìn yêu lang vây công, khiến quân phòng thủ dao động trước nguy cơ phòng tuyến tan vỡ. Đúng lúc tình thế nguy cấp, hơn trăm luyện thể sĩ của linh đội mặc cốt giáp tiến lên thành, nhanh chóng chém giết lang thú và vây yêu lang trên không. Một tiếng tru dài sau đó khiến toàn bộ đàn sói rút lui, khép lại lần dò xét đầu tiên với tổn thất lớn cho cả hai phía. Sau trận chiến, Trương Khuê cảm ơn Hàn Lập, nói về sự đáng sợ của yêu lang rồi tiết lộ một điều chưa được thuật lại khiến Hàn Lập rùng mình."},{"chuong":1279,"tieuDe":"Cuồng Thú Chi Triều Phần 4","tomTat":"Trương Khuê dựa vào phản ứng sợ hãi của yêu lang để dò xét thực lực thật của Hàn Lập, nhưng Hàn Lập không giải thích và tiếp tục tìm hiểu Kim Châm Quyết. Sang ngày thứ hai, đàn tiểu lang biến dị có thân pháp nhanh và lông mao chứa kịch độc khiến lực lượng thủ thành thương vong hơn phân nửa dù đã có quân tiếp viện cùng linh đội hỗ trợ. Trước nguy cơ An Viễn Thành thất thủ, Hàn Lập bình tĩnh tính toán dùng thân thủ và hai khỏa Diệt Tiên Châu để phá vây thoát thân. Sáng ngày thứ ba, gần nghìn hộ vệ, luyện thể sĩ và kỵ sĩ được tập hợp rồi phân về các đoạn phòng tuyến khác nhau. Nhóm Hàn Lập được Đại Hồ Tử dẫn tới một đoạn thành bị phá hủy nặng, nơi phi mãng biến dị từng phun độc vụ ăn mòn da thịt và đá, gây tổn thất hơn năm trăm người. Các luyện thể sĩ nhận nhiệm vụ kiềm chế cự mãng phá thành để binh lính thường đối phó xích mãng thú. Cuối chương, tiếng báo cầm thú vang lên từ chân trời, báo hiệu lực lượng yêu cầm đã nhập trận trong khi Hàn Lập vẫn thản nhiên quan sát linh thạch thấp giai."},{"chuong":1280,"tieuDe":"Uồng Thú Chi Triều Phần 5","tomTat":"Mấy trăm Báo Cầm Thú xuất hiện trên không, trong khi một biển Xích Mãng Thú trồi lên từ dưới đất và cùng tiến đánh Viễn An Thành theo hiệu lệnh của năm yêu thú đầu lĩnh. Hơn trăm tu sĩ do đại hán đầu bóng và cẩm bào nam tử của Kim Ngọc Tông dẫn đầu bay tới nghênh chiến đàn yêu cầm. Báo Cầm Thú tạo yêu vụ màu lục, phóng vô số lông chim hóa thành lục mang và giằng co với phù chú, lôi hỏa cùng pháp khí của các tu sĩ. Dưới mặt đất, từng tổ Xích Mãng cắn đuôi nhau thành chuỗi để vượt tường thành, khiến viện binh luyện thể sĩ ban đầu rối loạn trước khi quân thủ thành ổn định phòng tuyến bằng cung nỏ, khiên và cự nỏ. Hàn Lập trấn giữ một góc thành, dùng Kim Cương Quyết và kỹ pháp vận đao chém nhiều Xích Mãng bằng một thanh hậu bối đao bình thường. Khi cự mãng biến dị giết binh sĩ rồi tiếp tục phản kích sau khi mất đầu, hắn dùng quyền kình kim sắc xuyên thủng đuôi và phân thây hoàn toàn yêu thú."},{"chuong":1281,"tieuDe":"Cuồng Thú Chi Triều (6)","tomTat":"Hàn Lập liên tiếp tiêu diệt nhiều biến dị cự mãng, dùng đại đao, thân pháp hóa ảnh và xảo kình để phá hủy khả năng tái sinh của chúng. Đàn Báo Cầm Thú trên không ngưng tụ toàn bộ lục sắc yêu vụ thành một cự đại yêu cầm rồi bất ngờ lao xuống tường thành. Hàn Lập lấy Diệt Tiên Châu ra nhưng cất lại, lựa chọn dựa vào Kim Cương Quyết tầng thứ tư để chống đỡ trước khi bị lục vụ bao phủ. Đòn đánh phá sập tường thành, giết nhiều binh lính và luyện thể sĩ, đồng thời mở đường cho Báo Cầm Thú cùng Xích Mãng tràn vào An Viễn Thành. Tần Kỳ Quyền ngăn đại hán họ Uông tiếp tục cố thủ rồi dẫn hai đồng môn Kim Ngọc Tông vào thành cứu người. Khi Sa Trùng Thú từ Thanh La Sa Mạc xuất hiện, nhóm tu sĩ xác định bốn loại thú đang liên thủ và lần lượt giải tán. An Viễn Thành chính thức thất thủ trong lúc hoàng vụ cùng đàn côn trùng hung dữ áp sát."},{"chuong":1282,"tieuDe":"Nữ Đồng","tomTat":"Sau ba bốn ngày bị bốn loại yêu thú phối hợp tàn sát, An Viễn Thành hoàn toàn bị hủy diệt, phần lớn cư dân thiệt mạng và thú triều chính thức kết thúc. Tần Kỳ Quyền cùng hai đồng môn Kim Ngọc Tông quay lại phế tích tìm Hàn Lập vì một kế hoạch bí mật cần phàm nhân có thân thể cứng cỏi. Hàn Lập phá đá bước ra cùng nữ đồng Đại Nhi, người được hắn cứu sau khi nhóm luyện thể sĩ hộ tống nàng bị Lang thú giết sạch. Hắn tiết lộ mình chỉ bị thương nhẹ sau đòn đánh của Lục Vụ Yêu Cầm, đồng thời nhờ uy áp của đòn này mà phá được bình cảnh tầng thứ tư Kim Cương Quyết. Trong thời gian ẩn náu, Hàn Lập giết hơn một trăm yêu thú quanh nơi trú thân và giữ Đại Nhi ở lại cho đến khi thú triều rút đi. Vì muốn tìm thân nhân cho cô bé, hắn đồng ý theo Tần Kỳ Quyền tới nơi an toàn gặp chủ nhân đứng sau kế hoạch. Việc Hàn Lập âm thầm bước lên phi kiếm mà không bị phát hiện khiến Tần Kỳ Quyền thêm dè chừng năng lực của hắn. Sau gần nửa ngày phi hành, đoàn người tới doanh địa lều trại và nhà gỗ giữa vùng đồi núi, nơi một thanh niên áo lam ra đón và Tần Kỳ Quyền lập tức hỏi thăm phu nhân."},{"chuong":1283,"tieuDe":"Truy Sát","tomTat":"Phan Thanh đón Hàn Lập và Tần Kỳ Quyền vào nhà gỗ của thương đội, nơi Phương phu nhân nhận ra Đại Nhi là cháu gái của Triệu thành chủ. Phương phu nhân nghi ngờ việc ba đợt thú đàn đồng thời công kích An Viễn Thành, còn Tần Kỳ Quyền cho rằng người của Thiên Nguyên Thành sẽ phụ trách điều tra và giải thích vì sao các thành thị phàm nhân thường thiếu tu sĩ bảo vệ. Lan nhi cùng Lão quản gia Triệu phủ được gọi tới, giúp Đại Nhi đoàn tụ với người nhà và rời đi sau khi cảm tạ Hàn Lập. Tần Kỳ Quyền cảnh báo Triệu gia có thể gặp bất lợi vì Triệu thành chủ phải chịu trách nhiệm cho việc thành trì thất thủ, nhưng Hàn Lập không muốn can dự. Phương phu nhân sau đó tiết lộ thương đội đã phát hiện một vật có thể tăng khả năng Kết đan và đề nghị Hàn Lập phối hợp với Tần Kỳ Quyền. Cách đó vạn dặm, hai yêu cầm truy sát một Tử bào đại hán đang chạy trốn trên vật phẩm tứ diện. Khi vật phi hành mất tác dụng, đại hán lao nhanh xuống để tránh gai vàng và lôi quang rồi lẩn vào rừng cây."},{"chuong":1284,"tieuDe":"Hắc Phượng Tộc","tomTat":"Ba yêu xà và một Sa Trùng thú bắt sống Triệu thành chủ trong khu rừng rồi giao ông cho Phiệt cô cô, một nữ thành viên Hắc Phượng Tộc. Nàng ép ông khai tung tích Đại Nhi và tiết lộ cô bé là bán yêu mang huyết mạch Hắc Phượng, đồng thời thừa nhận đã liên thủ với các đàn thú công phá An Viễn Thành để tìm người. Triệu thành chủ cự tuyệt nên bị sưu hồn đến chết, qua đó để lộ việc ông đã cho cận vệ hộ tống Đại Nhi phá vây và ra lệnh xử tử cô nếu quá mười ngày không thể hội quân. Phiệt cô cô dùng hồng châu xác nhận Đại Nhi vẫn còn sống, ban đan dược cho đám yêu thú và ra hạn ba ngày để tìm ra cô bé. Sau khi nàng rời đi, một hắc bào lão giả đang ngụy trang thành khóm cây xuất hiện, phục nguyên thi thể Triệu thành chủ và định lợi dụng nó để tìm Đại Nhi trước Hắc Phượng Tộc. Một giọng nói băng lãnh bất ngờ phát hiện lão, khiến lão bỏ lại thi thể và hóa thành ám nguyệt tháo chạy."},{"chuong":1285,"tieuDe":"Cửu Huyền Minh Ngọc Đàm","tomTat":"Phiệt cô cô bí mật quay lại, dùng linh cầm hắc diễm thiêu hủy cả thân thể lẫn Nguyên Anh của hắc bào lão giả thuộc Minh Thi Cốc. Nàng tiếp tục lợi dụng Hoá Thi Thuật và huyết châu để biến thi thể Tử bào đại hán thành một phân thân có thể mô phỏng hành động, giọng nói của người chết rồi cho nó rời khỏi khu rừng. Tại nhà gỗ của Phương phu nhân, Tần Kỳ Quyền mời Hàn Lập giúp phá kim hành cấm chế để lấy Thất Diệp Âm Huyết Chi Thảo trong sào huyệt yêu thú. Đổi lại, nhóm tu sĩ hứa giúp hắn giành cơ hội ngâm Cửu Huyền Minh Ngọc Đàm, nơi có thể hỗ trợ luyện thể sĩ vượt bình cảnh và rút ngắn đáng kể thời gian tu luyện Minh Vương Quyết. Hàn Lập nhận lời sau khi kiểm tra bốn ngọc bội chứa tinh hồn mà nhóm Tần Kỳ Quyền giao làm bảo đảm, rồi cùng họ hẹn một ngày sau xuất phát. Đêm hôm sau, Triệu thành chủ đưa Đại Nhi tới gặp Hàn Lập trước khi hai ông cháu lên đường tới Thiên Nguyên Thành."},{"chuong":1286,"tieuDe":"Trảm Sát Tam Yêu","tomTat":"Trước khi rời doanh trại cùng Đại Nhi, Triệu thành chủ trao cho Hàn Lập một thanh đoản kiếm làm tín vật để tìm hậu nhân của người từng tu Kim Cương Quyết đến tầng sáu. Khi cự lang đột nhiên phát cuồng và bị Triệu thành chủ dùng hắc quang chế phục, Hàn Lập nhận ra dấu hiệu thi khí nên bí mật bám theo đoàn người. Tại gò đất cách thành hơn trăm dặm, Triệu thành chủ phối hợp với hai Xà Yêu và Sa Trùng thú giết sạch đoàn hộ tống, sát hại cự lang rồi cho yêu thú ăn hết thi thể để xóa dấu vết. Bị phát hiện đang ẩn nấp, Hàn Lập hiện thân, phá tan hắc thương và giao chiến với tam yêu. Hắn vận Kim Cương Quyết tầng thứ tư đến cực hạn, phá cốt mâu, né lục dịch ăn mòn và dùng sức mạnh thân thể tiêu diệt cả ba yêu thú. Sau đó, Hàn Lập phóng sát khí từng được Minh vương quyết luyện hóa, khiến đối phương biến sắc. Quan sát Triệu thành chủ và biểu hiện khác thường của Đại Nhi, hắn vạch trần thân thể đại hán trước mặt chỉ là một con rối rồi tiến lên định kết liễu."},{"chuong":1287,"tieuDe":"Truyền Thừa Châu","tomTat":"Phiệt cô cô hiện thân từ hắc sắc hỏa diễm, định giết Hàn Lập và khiến hắn cảm nhận một nguy cơ mãnh liệt hiếm có. Hàn Lập lấy ra hai viên Diệt Tiên Châu, buộc nàng phải dừng tay vì lo bị trọng thương, lộ yêu khí và遭 tu sĩ nhân loại truy sát do vi phạm hiệp nghị. Thiếu phụ tiếp tục dùng thanh âm cùng tử mang mê hoặc tâm thần hắn, nhưng Hàn Lập giả vờ trúng thuật rồi dùng linh nhãn lam quang phản kích khiến nàng suýt rơi khỏi không trung. Khi hắn muốn giữ Đại Nhi lại, nữ đồng xác nhận mình tự nguyện đi theo Phiệt cô cô để tiếp nhận thân phận bán yêu và sống cùng phụ thân. Phiệt cô cô tiết lộ Truyền Thừa Châu của Hắc Phượng Tộc đã được rót vào cơ thể Đại Nhi, giúp nàng từng bước tiếp nhận kinh nghiệm, bí thuật và ký ức truyền thừa. Hàn Lập tôn trọng quyết định của Đại Nhi và rời đi, còn Phiệt cô cô thiêu hủy con rối tử bào, thu hồi hắc hỏa rồi dùng khăn gấm đưa nữ đồng biến mất. Sáng hôm sau, Hàn Lập trở lại đoàn đoạt bảo cùng Phương phu nhân, Trương Khoa và các hộ vệ, trong khi mọi người đều giữ im lặng về mối liên hệ giữa hắn với Thiên Đông Thương Hào."},{"chuong":1288,"tieuDe":"Ngu Dương Thành","tomTat":"Ngu Dương Thành là một cổ thành bậc trung tại Thiên Nguyên Cảnh, nổi tiếng với truyền thống luyện thể, Thánh Tháp lưu giữ nhiều pháp môn và ngành chế tạo linh cụ phát triển. Tại Long Hưng Thương Hội, Phạm lão đệ nóng lòng chờ Hàn đại sư mang tới linh cụ cuối cùng. Hàn đại sư trao cho ông một thanh trường kiếm đỉnh cấp có thể hóa khí thành Kim Giao, đủ sức giúp thương hội củng cố địa vị và tranh quyền độc quyền buôn bán. Ông cho biết mình đã mai danh ẩn tích và chế tạo linh cụ suốt mười năm để báo đáp việc Phạm lão đệ từng cứu mình khỏi nguy cơ khi tu luyện. Sau khi truyền hơn nửa y bát cho các học đồ và giúp Long Hưng trở thành một trong những hội đấu giá lớn nhất thành, ông từ chối ở lại vì muốn tiếp tục tiến bước trên con đường luyện thể. Ra ngoài thành hơn mười dặm, người trung niên gỡ bỏ râu cùng lớp ngụy trang, để lộ dung mạo thật của Hàn Lập. Hàn Lập bỏ lại chiến thú hình hươu, tự mình chạy về phương xa rồi dần biến mất nơi chân trời."},{"chuong":1289,"tieuDe":"Phi Hạt","tomTat":"Hàn Lập mất khoảng nửa năm từ Ngu Dương Thành trở lại phế tích An Viễn Thành và xác định Kim Cương Quyết đã chạm bình cảnh đệ thất tầng. Hắn hồi tưởng lần công pháp cắn trả khiến tu vi suýt tụt xuống đệ tứ tầng, nhưng được Phạm lão đệ dùng đan dược quý cứu và đưa về thành. Sau đó, Tần Kỳ Quyền thực hiện lời hứa cho hắn vào Cửu Huyền Minh Ngọc Đàm, nhờ vậy hắn đột phá đệ lục tầng chỉ trong vài ngày. Sau hơn hai mươi năm tĩnh tu, Hàn Lập quyết định dùng những trận chiến sinh tử với yêu thú để phá bình cảnh, đồng thời trở lại Thanh La Sa Mạc tìm bảo vật đã chôn. Tại sa mạc tĩnh lặng như tử địa, hắn phát hiện mười một xác Lục Dực Sương Công có thân thể cứng đến mức roi bạc của hắn không thể làm tổn hại. Cá thể còn sống đã đạt giai đoạn thành thục, có cảnh giới gần Hóa Thần kỳ đại thành và khả năng điều động thiên địa nguyên khí. Hàn Lập lần theo cảm ứng tâm thần rồi chứng kiến con linh trùng này giao chiến dữ dội với hàng vạn phi hạt ngũ sắc có thể ngưng tụ thành một Hạt Vương khổng lồ."},{"chuong":1290,"tieuDe":"Thu Hồi Bảo Vật","tomTat":"Lục Dực Sương Công dùng hàn quang đóng băng và đánh tan Cự Hạt do vô số Phi Hạt tụ thành, sau đó thôn phệ những Phi Hạt đã đông cứng. Hàn Lập nhận ra linh trùng đã tăng mạnh pháp lực, sơ bộ mở linh trí và chủ động cắt đứt quyền khống chế của hắn. Không thể vận dụng pháp lực, hắn âm thầm chuẩn bị hai khỏa Diệt Tiên Châu, nhưng mối liên hệ tâm thần lâu năm khiến Lục Dực Sương Công từ bỏ ý định gây bất lợi rồi tự bay đi. Hàn Lập phá lớp cát, thu hồi túi trữ vật cùng ba túi linh thú và xác nhận Phệ Kim Trùng, Đề Hồn Thú vẫn an toàn. Sau khi chôn kín các vỏ xác và xóa dấu vết, hắn lên đường về phía một tòa thành gần Yêu Thú Chi Địa. Vùng giáp ranh Nhân–Yêu là nơi chưa được khai phá chính thức, tập trung nhiều yêu thú, cổ thú và cường giả nhưng cũng giàu linh mạch, linh dược cùng đặc sản quý hiếm. Cao tầng hai tộc hạn chế lực lượng cấp cao tiến vào để tránh đại chiến, song tu sĩ và Luyện thể sĩ vẫn tìm đến săn yêu thú và cầu cơ duyên. Sau hơn một năm ngày đêm hành tẩu, Hàn Lập cuối cùng tới được vùng biên cảnh."},{"chuong":1291,"tieuDe":"Thiên Nguyên Vũ Cụ","tomTat":"Lạc Nhật Chi Mộ được giới thiệu là lòng vực khổng lồ giữa địa bàn nhân tộc và yêu tộc, tương truyền hình thành khi một mặt trời rơi xuống trong Chân linh chi chiến thời viễn cổ. Hàn Lập tiến vào Lạc Nhật Thành của nhân tộc, một trong ba đại thành của Thiên Nguyên Cảnh, rồi quan sát thị trường pháp khí và linh cụ tại đây. Vì chưa quen đường, hắn thuê tu sĩ Luyện Khí kỳ Điền Hưng làm người dẫn đường với giá mười hai khối linh thạch mỗi ngày. Điền Hưng giới thiệu bố cục tám khu vực của thành và cho biết khu trung tâm tập trung nhiều bảo vật cao cấp, thậm chí có nơi bán Linh Bảo. Y còn tiết lộ bộ năm kiện Thiên Nguyên Vũ Cụ từng được Thiên Nguyên Thánh Hoàng sử dụng sẽ xuất hiện tại đấu giá hội trong vòng ba hoặc bốn tháng. Dù đủ linh thạch tranh mua bộ linh cụ, Hàn Lập lo việc tham gia đấu giá sẽ khiến mình bị chú ý. Hắn vì thế quyết định tự luyện chế hai kiện đỉnh bậc linh cụ để chuẩn bị cho hành trình tìm cơ duyên đột phá trong Lạc Nhật Chi Mộ."},{"chuong":1292,"tieuDe":"Hoàng Lương Linh Quân","tomTat":"Sau khi luyện thành Kim Cương Quyết, Hàn Lập không còn vừa ý với những vật liệu và linh cụ thông thường nên được Điền Hưng dẫn tới Khung Vũ Cát. Trên đường, họ chứng kiến linh xa xanh nhạt của Hoàng Lương Linh Quân bay qua Lạc Nhật Thành và Hàn Lập biết vị này là một tu sĩ Hợp Thể sơ kỳ được xem như đệ nhất cường giả địa phương. Tại Khung Vũ Cát, Điền Hưng kể rằng chưởng quỹ Tư lão từng là cao giai luyện thể sĩ nhưng đã mất toàn bộ khí lực vì trúng quái độc tại Lạc Nhật Chi Mộ. Trong lúc Tư lão lên lầu lấy vật liệu, Thanh niên họ Tiền và Nữ tử họ Lữ tiến vào sau khi đánh ngã hai quái thú giữ cửa. Thanh niên họ Tiền tiết lộ đồng bạn là hậu nhân của Hoàng Lương Linh Quân, khiến Tư lão miễn cưỡng bỏ qua sự việc. Cuối cùng, Tư lão mang xuống hai hộp gấm một lớn một nhỏ, còn Hàn Lập yêu cầu ông giới thiệu những vật liệu bí ẩn bên trong trước khi xem xét."},{"chuong":1293,"tieuDe":"Ngân Tâm Thạch Và Thiên Tâm Đan","tomTat":"Tại Khung Vũ Cát, Hàn Lập đánh tan thủ đoạn cướp đoạt của thanh niên họ Tiền và kiên quyết giữ quyền mua Ngân Tâm Thạch cùng khối khoáng thạch xám biến dị. Hắn không lay chuyển trước danh tiếng của Cầu Long Tôn Giả, mức giá gấp đôi hay bình Thiên Tâm Đan do nữ tử họ Lữ đề nghị, cuối cùng trả đủ linh thạch để hoàn tất giao dịch. Sau vài ngày thu thập thêm tài liệu, Hàn Lập chia tay Điền Hưng, thuê phòng bế quan luyện chế linh cụ suốt một tháng rồi rời Lạc Nhật Thành. Tiến vào Lạc Nhật Chi Mộ qua hạp cốc do Nhân Tộc quản lý, hắn từ chối lập đội và mang theo chiến giáp, trường thương mới, Địa Giao Cân cùng hai viên Diệt Tiên Châu để tự bảo vệ. Trong những tháng săn bắt tiếp theo, Hàn Lập dùng La Yên Bộ xuyên rừng, điều khiển Địa Giao Cân chém đôi cự hùng một sừng và dùng trường thương tiêu diệt đàn viên hầu cùng một yêu hầu ba đầu cấp Kết Đan. Sau khi hắn rời đi, hai Linh Tộc là Thiên Anh và Hoàng Thạch Công hiện thân, nhưng từ bỏ ý định tập kích vì nhận thấy thần thức của hắn mạnh ngang tu sĩ Hóa Thần. Cả hai chuyển sang truy tìm một kẻ phản nghịch Khí Linh Tộc, quyết ngăn kẻ này hội hợp với người tiếp ứng và trao Thần Huyết cho Nhân Tộc."},{"chuong":1294,"tieuDe":"Linh Tộc Hiện Ra","tomTat":"Hàn Lập một mình đi qua cửa hạp cốc do Nhân Tộc quản lý để tiến vào Lạc Nhật Chi Mộ, bất chấp nhiều nhóm tu sĩ mời đồng hành. Hắn giả dạng cao giai luyện thể sĩ, mang theo chiến giáp, trường thương xám bạc, Địa Giao Cân và hai viên Diệt Tiên Châu làm át chủ bài. Sau khi tiến vào rừng nguyên thủy, Hàn Lập dùng La Yên Bộ di chuyển và điều khiển Địa Giao Cân chém đôi một con cự hùng cùng cây đại thụ phía sau. Ba tháng săn bắt giúp hắn tiêu diệt hơn hai mươi viên hầu và một yêu hầu ba đầu cấp Kết Đan. Khi Hàn Lập rời đi, Thiên Anh và Hoàng Thạch Công bí mật hiện thân; Thiên Anh ngăn đồng bạn tập kích vì nghi Hàn Lập là tu sĩ Hóa Thần che giấu linh lực. Cuộc đối thoại của họ hé lộ nhiều nhánh Linh Tộc đang truy bắt một phản nghịch thuộc Khí Linh Tộc, nhằm ngăn kẻ đó hội hợp với người tiếp ứng của Nhân Tộc và chuyển giao Thần Huyết."},{"chuong":1295,"tieuDe":"Phi Nga","tomTat":"Hoàng Thạch Công và nữ tử quần lục xác nhận phản nghịch Linh Tộc đã bị trọng thương, mang dấu hiệu cảm ứng và khó thoát khỏi vòng phong tỏa. Tại Lạc Nhật Thành, Lam Thành chủ triệu tập Hoàng Lương Linh Quân cùng hai cao thủ khác, tiết lộ nhiệm vụ tiếp ứng bắt nguồn từ Thánh Hoàng Cung và có một đặc sứ đang trên đường tới nhận trọng vật. Cuộc họp bị một phân thân Huyễn Diễm Nga nghe lén; dù Hoàng Lương phát hiện và đánh trúng, linh trùng vẫn tự bạo tạo huyễn tượng để phân thần mang tin tức chạy thoát. Thiếu niên họ Nghê nhận được tình báo, đề xuất hôn sự giữa hậu bối Quỳnh Thử Tộc với Đại Nhi rồi sai Hắc Phượng Tộc yêu nữ triệu tập Yêu Tộc tiến vào Lạc Nhật Chi Mộ. Hắn còn quyết định âm thầm bám theo đoàn Hoàng Lương nhằm đoạt trọng vật trước Nhân Tộc. Sau đó Nhân Tộc và Yêu Tộc đồng loạt treo trọng thưởng, khiến cuộc tranh giành trong Lạc Nhật Chi Mộ trở nên dữ dội. Hàn Lập hoàn toàn chưa biết biến động này và đang đứng trước cuộc chiến hung hiểm nhất kể từ khi tiến vào Lạc Nhật Chi Mộ."},{"chuong":1296,"tieuDe":"Quái Xà, Thủy Tiễn, Ngân Thủ","tomTat":"Hàn Lập giao chiến dữ dội với một tiểu thú hình dáng gần giống báo gấm, có tốc độ vượt La Yên Bộ, móng vuốt sắc bén và khả năng tạo hơn ba mươi thân ảnh. Khi hắn chuẩn bị thả Phệ Kim Trùng, một tiếng gáy từ xa khiến tiểu thú đột ngột thu hư ảnh rồi chạy sâu vào rừng. Sau ba ngày lĩnh hội, Hàn Lập tuy chưa phá được bình cảnh nhưng xác nhận chiến đấu sinh tử có thể giúp hắn tìm lại cảnh giới, vì vậy quay lại tìm đối thủ rồi rời sơn mạch khi không thấy tung tích. Hơn mười ngày sau, một nhóm Luyện Thể sĩ Nhân tộc giao chiến với đàn quái xà đỏ bên hồ lớn và cả hai phía bất ngờ bị vô số thủy tiễn xuyên thủng. Xà Vương tránh được đợt công kích đầu tiên nhưng bị hai ngân thủ chặn bắt, chấn gãy răng nanh và ngắt đứt đầu. Sau đó Thiết Nhận cùng Thủy Mị hiện thân, nhận ra nhau và nhắc tới Xích Diệt. Một nhân vật bí ẩn cuối cùng xuất hiện giữa hỏa diễm dưới hình thái Hỏa nhân, nhưng danh tính của người này vẫn chưa được xác nhận."},{"chuong":1297,"tieuDe":"Linh Tộc Viện Quân","tomTat":"Hỏa nhân và Ngân sắc nhân ảnh tìm Thủy Mị, nhờ ông dùng thần thông thủy tính xuống Chích Quang Đàm bắt kẻ phản nghịch mang Thần Huyết. Thủy Mị quyết định chờ Húc Thiên dẫn viện quân Khí Linh Tộc tới, đồng thời chỉ ra rằng cao thủ Linh Tộc đang bị Dạ Xoa Tộc ghìm chân và không thể tùy tiện gây chiến lớn với cả Nhân tộc lẫn Yêu tộc. Bên ngoài Hỗn Độn Cốc, Cung trang thiếu phụ của Hắc Phượng Tộc ra lệnh phong tỏa cốc khẩu và phái người tìm Hoàn tiền bối. Hoàng Lương Linh Quân cùng Lam thành chủ dẫn hơn mười tu sĩ tiến về thung cốc, trên đường bàn luận về lời đồn Thượng Cổ Cự Nhân và sự nguy hiểm của Chích Quang Đàm. Một thiếu niên Yêu tộc mang theo Huyễn Diễm Phi Nga bí mật theo dõi đoàn người từ dưới thảo nguyên. Ở một nơi khác, Hàn Lập dùng Trường Thương gắn linh thạch giết sạch đàn Phi Lang và lấy kim quang hộ thể chống toàn bộ phong nhận. Sau khi thay số linh thạch đã cạn, hắn phát hiện một gốc linh chi dị thảo ngân sắc phủ linh vụ trắng ngà và tỏa hương thơm mê người."},{"chuong":1298,"tieuDe":"Gặp Lại Tiểu Thú","tomTat":"Hàn Lập nhận ra Thái Ất ngân tinh chi, đánh giá công dụng phòng ngự của linh dược rồi thu nó vào bình ngọc để sau này bán cho luyện thể sĩ trung giai. Trong lúc suy xét về sự nguy hiểm của thế giới man hoang, hắn bất ngờ gặp lại tiểu thú từng giúp mình đốn ngộ, nhưng nó đang hoảng hốt và lập tức bỏ chạy. Một tiểu kiếm xuất hiện chặn đường rồi hóa thành linh tướng Linh Tộc mặc bạch bào, khiến Hàn Lập phải rút lui vì đang mất pháp lực. Linh tướng phóng năm đạo kiếm ti công kích, phá hủy hắc sắc trường thương và chiến giáp, buộc Hàn Lập vận Kim Cương Quyết tầng bảy cùng quyền phong để cầm cự. Tiểu thú phân hóa thành mười thân ảnh, nhưng chín ảnh giả bị kiếm võng phá tan và chân thân tiếp tục bị linh tướng truy đuổi. Hàn Lập dùng chướng nhãn pháp nấp gần chiến trường, cầm sẵn hai viên Diệt Tiên châu để dự phòng và thành công khiến đối phương chuyển mục tiêu. Sau khi thoát hiểm, hắn lo ngại sự xuất hiện bất thường của một linh tướng tại Lạc Nhật Chi Mộ báo hiệu một biến cố lớn sắp xảy ra."},{"chuong":1299,"tieuDe":"Phệ Viêm","tomTat":"Hàn Lập trở lại nơi vừa giao thủ và phát hiện hai linh cụ do mình dày công luyện chế đã vỡ nát, nhưng không hối hận vì chúng đã giúp hắn giữ mạng trước đối thủ cấp linh tướng. Khi hắn định rời đi, Húc Thiên, Phệ Viêm và một thiếu nữ Linh Tộc mang hàn vụ xuất hiện chặn đường. Phệ Viêm nhận định Hàn Lập là mục tiêu thích hợp vì hắn có thể biết địa hình Hỗn Độn Cốc và không mang pháp lực, rồi được Húc Thiên cho phép ra tay. Hàn Lập vận chuyển Kim Cương Quyết và chuẩn bị dùng hai viên Diệt Tiên Châu, song bị kình lực vô hình của Húc Thiên ép lún xuống đất và làm tê liệt toàn thân. Phệ Viêm hóa thành hỏa giao chui vào đầu hắn, khiến hắn phát cuồng phá hủy cây cối trong thời gian dài hơn dự kiến. Cuối cùng, thân thể Hàn Lập trở lại với vẻ mặt vô cảm và dùng giọng của Phệ Viêm trả lời Húc Thiên, đồng thời tiết lộ rằng tinh thần và thần thức của mục tiêu lớn hơn luyện thể sĩ thông thường."},{"chuong":1300,"tieuDe":"Tam Tộc Tề Tựu","tomTat":"Trước sức ép từ yêu khí đang tiến đến cửa Hỗn Độn cốc, Linh tộc triển khai hàng loạt mộc điểu và thạch cự nhân, còn Hoàng Thạch Công cùng Thiên Anh hiện thân nghênh chiến. Cục diện thay đổi khi Hoàn Thương Kì, trưởng lão Quỳnh Thử Tộc có tu vi Luyện Hư trung kỳ, dẫn viện quân Yêu tộc xuất hiện và kêu gọi Linh tộc quy thuận hai tộc Nhân–Yêu. Hai linh tướng cự tuyệt, tin rằng các vị thánh linh vẫn đủ sức bảo vệ Linh tộc. Hoàn Thương Kì sau đó vạch trần nơi ẩn náu của Hoàng Lương Linh Quân và Lam Thành chủ, khiến ngọc chu của nhóm chỉ huy Nhân tộc phải hiện khỏi hư không. Hoàng Lương nhận ra Huyễn Diễm Nga từng nghe trộm cuộc bàn bạc tại Lạc Dương, qua đó hiểu vì sao kế hoạch mai phục bị phát hiện. Trong cuộc thương lượng tiếp theo, Hoàn Thương Kì và Hoàng Lương cùng bộc lộ nỗi lo về đại thiên kiếp, đồng thời nhắc lại khả năng hợp tác tiến vào Mãn Hoang tìm cơ duyên và bảo vật độ kiếp. Hai người cuối cùng đồng ý tạm liên thủ bắt phản nghịch Linh tộc trước rồi mới định giá và phân chia vật thu được. Lam Thành chủ lập tức phát tín hiệu, khiến toàn bộ tu sĩ và luyện thể sĩ Nhân tộc đang mai phục đồng loạt hiện thân, hoàn tất thế tam tộc cùng tụ tại Hỗn Độn cốc."},{"chuong":1301,"tieuDe":"Đại Hiển Thần Thông","tomTat":"Hoàng Lương Linh Quân ra lệnh Nhân tộc phối hợp với Yêu tộc truy kích lực lượng Linh Tộc đang rút về cốc khẩu Hỗn Độn Cốc. Cuộc truy kích rơi vào bẫy của Húc Thiên khi Huyết Liên hóa thành Huyết Hà, khiến gần một nửa liên quân Nhân–Yêu tiêu biến bất chấp các biện pháp phòng ngự. Hoàn Thiên Kỳ và Hoàng Lương Linh Quân hợp sức ngăn Huyết Hà, sau đó giao chiến với Húc Thiên trong khi Hoàn Thiên Kỳ phát hiện đội hình Ngũ Hành Linh Tộc thiếu người của Thủy Tộc và nhận ra đối phương đang kéo dài thời gian. Hai phe lập tức tổng công kích; Cận đạo hữu hóa thành hắc sắc cự nhân quyền đấu với Thiết Nhận, còn Cung trang thiếu phụ hóa Hắc Sắc Hỏa Phượng thiêu hủy Mộc Điểu rồi vượt qua cốc khẩu. Lam Thành chủ dùng bảy phi kiếm quét sạch Thạch Nhân để mở thông đạo cho một nhóm Nhân–Yêu tiến vào cốc. Hàn Lập là người cuối cùng theo nhóm nhập cốc, phải điều động Hỏa Linh Khí để độn hành vì không có pháp lực. Giữa không gian tro xám kỳ lạ trong Hỗn Độn Cốc, hắn dừng lại và gọi ra một ngân sắc hỏa điểu bay quanh thân."},{"chuong":1302,"tieuDe":"Thái Nhất Hoá Thanh Phù","tomTat":"Hàn Lập phối hợp thần niệm với Thái Âm Chân Hỏa để nuốt sạch Phệ Viêm, thu cả Hỏa Linh căn, ký ức và xích hồng bảo châu rồi đặt tên hỏa điểu mới là Phệ Linh Thiên Hỏa. Từ ký ức thu được, hắn biết một kẻ phản nghịch Linh Tộc đã đánh cắp Linh Tộc Thần Huyết, bí bảo có thể dùng luyện đan, luyện thể và hỗ trợ đột phá bình cảnh. Do Hỏa Linh lực tạm thời chỉ tồn tại khoảng một tháng, Hàn Lập quyết định mạo hiểm tìm kiếm Thần Huyết trước khi pháp lực lại suy kiệt. Khi Thổ Độn Thuật bị lực cản quỷ dị dưới Hỗn Độn Cốc ngăn lại, hắn chuyển sang kích hoạt Thái Nhất Hóa Thanh Phù do mình luyện theo Kim Khuyết Ngọc Thư. Linh phù giúp hắn ẩn thân trước cả tu sĩ Hóa Thần, nhưng khiến hắn không thể điều động linh lực hay pháp bảo trong lúc hóa thanh. Hàn Lập nhờ đó tiến sâu tới Chích Quang Đàm, nơi nhóm cao giai Nhân Tộc do Lam Thành chủ và Đầu Đà đứng đầu đang giằng co với phe Yêu Tộc do cung trang thiếu phụ Hắc Phượng Tộc cùng ba thanh niên gầy ốm dẫn dắt."},{"chuong":1303,"tieuDe":"Chích Quang Đàm","tomTat":"Hàn Lập ẩn mình quan sát khi Lam Thành chủ và Cung trang thiếu phụ tranh cãi về quyền tiến vào Chích Quang Đàm, còn ba thanh niên cao gầy xác nhận họ là ba phân thân của Tam Thủ Nguyệt Lang. Trước lúc hai phe Nhân, Yêu trở mặt, thủy đàm bất ngờ phóng ra những quang trụ khủng khiếp, khiến nhiều Hóa Hình yêu tu và tu sĩ Nguyên Anh biến mất dù đã dùng các biện pháp phòng hộ. Năm hoàng trụ màu vàng trồi lên quanh đầm; Lam Thành chủ dùng năm cự kiếm chém xuống nhưng chỉ để lại vết mờ, còn vết chém phun ra dịch xanh như từ một vật sống. Sau đó Lạc Dương Tinh xuất hiện, khiến Đầu Đà, Cung trang thiếu phụ và Tam Thủ Nguyệt Lang lao tới tranh đoạt, trong khi Hàn Lập vẫn giữ kín hành tung vì chỉ nhắm tới Thần huyết. Đầu Đà bị hấp lực vô hình kéo xuống thủy đàm, khiến phe Yêu tộc vội rút lui và Lam Thành chủ cũng bất ngờ đào tẩu về phía cốc khẩu. Năm hoàng trụ khác tiếp tục mọc lên, nước đầm hóa thành xoáy lớn và mặt đất hai bên nứt vỡ. Hai cự vật bí ẩn từ dưới lòng đất trồi lên, khiến Hàn Lập sửng sốt khi nhìn rõ chân diện mục của chúng."},{"chuong":1304,"tieuDe":"Thượng Cổ Cự Nhân","tomTat":"Hàn Lập phát hiện mười hoàng trụ quanh Chích Quang Đàm thực chất là những ngón tay khổng lồ, còn đáy đầm chính là hốc mắt của một sinh linh đang thức tỉnh. Lạc Dương Tinh nhập vào con ngươi, sau đó Thượng Cổ Cự Nhân cao hàng trăm trượng trồi khỏi lòng đất và dùng hấp lực kéo Tam Thủ Yêu Lang cùng các bảo vật về phía miệng. Ba Yêu tu Lang tộc dù dung hợp bản thể và dốc sức chống đỡ vẫn rơi vào tuyệt cảnh, nhưng Hoàng Thiên Kỳ kịp xuất hiện, dùng hai quang quyền cứu họ rồi ngưng tụ gương xanh tiếp lấy. Hàn Lập suy đoán tên Linh Tộc phản nghịch cùng bình Thần Huyết có thể đã bị Cự Nhân nuốt, song vẫn không định rút lui dù biết sức mạnh đáng sợ của nó. Hoàng Lương Linh Quân xuất hiện và cùng Hoàng Thiên Kỳ bàn việc liên thủ giết Cự Nhân đang trọng thương, đồng thời thỏa thuận phân chia Lạc Dương Tinh cùng đồ vật của Linh Tộc phản nghịch. Cuối chương, Lam Thành chủ, cung trang thiếu phụ và một số người của Nhân Yêu lưỡng tộc quay lại, trong khi phía Linh Tộc hoàn toàn vắng bóng."},{"chuong":1305,"tieuDe":"Cuộc Chiến Với Cự Nhân","tomTat":"Sau khi buộc Húc Thiên dẫn người Linh Tộc rút khỏi trận chiến ngoài cốc, Hoàn Thiên Kỳ và Hoàng Lương Linh Quân tiến vào Hỗn Độn Cốc rồi giao chiến với Thượng Cổ Cự Nhân. Hai người hóa giải bạch ti và cuồng phong của đối thủ, nhưng nhanh chóng phát hiện Cự Nhân có bất diệt chi thể khi chiếc ngón cái bị chém đứt tái sinh trong lục quang. Cự Nhân lấy ra thạch bổng khổng lồ, còn Hoàn Thiên Kỳ triệu Huyền Diễm Nga và hóa thú trong khi Hoàng Lương Linh Quân xuất Nguyên Anh điều khiển Bạch Ngọc Đại Ấn. Trận chiến cấp Luyện Hư làm địa hình Hỗn Độn Cốc bị tàn phá và thiên địa nguyên khí hỗn loạn dữ dội. Hàn Lập ẩn trên cao quan sát, nhờ đó lĩnh ngộ thêm về cách vận dụng linh khí của các tồn tại Luyện Hư và phát hiện một bóng người trong suốt đang bí mật quan chiến. Sau thời gian dài bị hai đối thủ du đấu tiêu hao, Cự Nhân dần chậm lại và bị Hoàn Thiên Kỳ chặt đứt một chân. Vết thương lần này không thể tái sinh, báo hiệu cuộc chiến đã sắp đi đến hồi kết."},{"chuong":1306,"tieuDe":"Tranh Giành Thần Huyết","tomTat":"Hoàng Lương Linh Quân và Hoàn Thiên Kỳ dùng nhiều pháp bảo cùng thần thông hợp sức vây công Cự Nhân độc nhãn, trong khi Hàn Lập ẩn thân quan sát gần chiến trường. Cự Nhân chống trả bằng Lạc Dương Tinh, tinh quang từ độc nhãn, Thạch Bổng và thần lực, nhưng cuối cùng vẫn bị chặt tay chân, phá hủy đầu và tâm tạng. Sau trận chiến, Hoàng Lương Linh Quân thu lấy Lạc Dương Tinh còn Hoàn Thiên Kỳ mổ thi thể Cự Nhân, tìm thấy bát ngọc mất linh tính cùng một tiểu bình đỏ tươi chứa Thần Huyết. Húc Thiên bất ngờ hiện thân, đánh lén Hoàn Thiên Kỳ, đoạt tiểu bình rồi hóa thành huyết vân bỏ chạy. Hoàn Thiên Kỳ triệu Phi Nga khổng lồ dùng thất sắc quang hà chặn đường, đồng thời Hoàng Lương Linh Quân phóng kiếm khí truy kích. Phệ Viêm đang ẩn nấp bí mật truyền âm xin nhận Thần Huyết để dùng độn thuật mang bảo vật chạy trước. Nhận ra đồng tộc nhờ thiên phú cảm ứng, Húc Thiên ném tiểu bình về phía Phệ Viêm, nhưng việc tiếp nhận và đào thoát chưa có kết quả."},{"chuong":1307,"tieuDe":"Trận Chiến Giữa Các Cấp Bậc Luyện Hư","tomTat":"Giữa lúc Huyết Vân ngưng thành Huyết Liên và hút các đạo kiếm quang, Hàn Lập đang ẩn thân âm thầm thu lấy tiểu bình bị đánh văng khỏi chiến trường. Hoàn Thiên Kỳ phát hiện có người can thiệp và dùng yêu phong công kích, nhưng Húc Thiên vô tình chém đôi luồng yêu phong, mở đường cho Hàn Lập rời chỗ ẩn nấp. Hoàng Lương Linh Quân bất ngờ dùng Bạch sắc Ngọc Ấn ép Hàn Lập hiện thân, khiến Hư Thiên Đỉnh và đôi cánh thanh bạch của hắn bại lộ, qua đó làm Húc Thiên nhận ra hắn không phải Phệ Viêm và Hoàng Lương xác định hắn là tu sĩ Nhân Tộc. Hoàn Thiên Kỳ ngăn Húc Thiên truy bắt để tiếp tục lĩnh giáo Huyết Sát Linh Liên, đồng thời giao Hàn Lập cho Hoàng Lương xử lý. Hàn Lập dùng Kim Sắc Phi Kiếm chống kiếm luân và ba mươi sáu đạo thanh quang, rồi vận dụng Phá diệt pháp mục buộc Hoàng Lương đang ẩn hình phải hiện thân. Khi Ngũ Sắc Ngọc Phủ giáng xuống, tiểu sơn đen nhánh của Hàn Lập phóng hôi sắc hào quang áp chế các pháp bảo và trì hoãn đòn đánh trong chốc lát. Nhờ khoảng thời gian đó, Hàn Lập hoàn tất Huyết Ảnh Độn, hóa thành huyết quang bỏ chạy về phía chân trời. Hoàng Lương Linh Quân, Húc Thiên và Hoàn Thiên Kỳ lập tức hóa thành ba đạo kinh hồng truy đuổi với tốc độ không kém hắn."},{"chuong":1308,"tieuDe":"Uy Lực Của Hoả Linh","tomTat":"Hàn Lập dùng Huyết Ảnh Độn lao khỏi Hỗn Độn cốc trong khi Húc Thiên, Hoàng Lương Linh Quân và Hoàn Thiên Kỳ bám sát phía sau. Hắn kích nổ hai viên Thiên Tiên Châu, tạo lốc xoáy cuốn Húc Thiên vào, còn hai người kia nhân cơ hội công kích Húc Thiên để ngăn hắn thoát khốn. Tại cốc khẩu, Ngân sắc Hỏa Linh do Hàn Lập bố trí tiếp tục đốt tan kiếm khí và yêu phong, hóa thành hỏa điểu rồi tung hỏa cầu ép hai kẻ truy đuổi phải phòng thủ. Nhờ những thủ đoạn cản đường liên tiếp, Hàn Lập rời khỏi tầm mắt và dùng thuật ẩn nấp xóa sạch dấu vết linh lực cùng hơi thở, khiến thần niệm Luyện Hư cũng không thể tìm ra. Hoàng Lương Linh Quân đề nghị huy động nhân thủ phong tỏa vài ngàn dặm và thỏa thuận dùng Lạc Dương Tinh đổi lấy việc Hoàn Thiên Kỳ cho Huyễn Diễm Nga thi triển Thiên Nga Thuật. Húc Thiên sau đó phá tan lốc xoáy trong huyết liên, tuyên bố sẽ không bỏ qua việc bị đánh lén rồi tiếp tục truy tìm Hàn Lập. Hoàng Lương Linh Quân và Hoàn Thiên Kỳ cũng chia nhau triệu tập lực lượng, biến cuộc truy đuổi thành một đợt phong tỏa quy mô lớn."},{"chuong":1309,"tieuDe":"Thiên Kiếp Hàng Lâm","tomTat":"Hàn Lập chạy xa khỏi chiến trường, thay đổi dung mạo, thu liễm hoàn toàn linh khí rồi đào thạch động ẩn náu. Trong động, hắn lấy Huyết sắc tiểu bình ra kiểm tra và xác nhận những giọt chất lỏng tím sậm bên trong chính là Linh Tộc Thần Huyết. Nhờ không còn tỏa ra linh khí, hắn tránh được nhiều đợt thần niệm lục soát và chỉ kín đáo rời đi sau khi tình hình đã lắng xuống. Hoàng Lương Linh Quân điều tra vụ mất Thần Huyết suốt nhiều năm nhưng không tìm được manh mối, sau đó rời Lạc Nhật Thành để cùng Hoàn Thiên Kỳ tiến vào Man Hoang thế giới. Nhiều năm sau, một bóng người chưa rõ danh tính bế quan trong cự sơn suốt trăm năm, bên cạnh là Huyết sắc tiểu bình dường như đã rỗng. Thương đội của Hỏa lão tiến đến Xuyên Vân Sơn sau khi thanh trừ yêu thú và dự định mở một thương lộ mới. Đúng lúc ấy, mây đen, hồ quang kim ngân và cuồng phong trắng bao phủ đỉnh núi, báo hiệu một loại Thiên Kiếp mà Hỏa lão không thể xếp vào Tiểu Thiên Kiếp hay Đại Thiên Kiếp."},{"chuong":1310,"tieuDe":"Lưỡng Sắc Lôi Kiếp","tomTat":"Một đoàn xe dừng gần cự sơn để quan sát thiên kiếp có thiên lôi đồng thời mang hai màu kim và ngân, dị tượng mà Hỏa lão không thể xếp vào những loại lôi kiếp thông thường. Ngân sắc điện hồ phá hủy đỉnh núi, còn kim sắc điện hồ xuyên qua núi đá đánh thẳng vào lòng núi, buộc người độ kiếp phải bay ra ngoài. Người này dùng cự đỉnh thu ngân lôi và kết kim sắc điện võng đối kháng kim lôi, nhưng hai phòng tuyến dần suy yếu khi thiên kiếp tăng cường. Khi lôi điện chuyển thành vô số lưỡng sắc lôi cầu, cự đỉnh bị hao tổn còn điện võng liên tục tan vỡ. Người độ kiếp tiếp tục thi triển Nguyên Từ Thần Quang và biến Nguyên Từ Sơn thành cự sơn để phá lôi cầu thành điện hồ rồi thu chúng vào thân núi. Người ấy chính là Hàn Lập, đã tiềm tu trong bụng núi hơn trăm năm, luyện Kim Cương Quyết tới đại thành và dùng linh dược ngưng tụ lại Nguyên Anh từng bị hư hóa. Sự khôi phục của Nguyên Anh bất ngờ dẫn tới lưỡng sắc thiên kiếp, khiến Hàn Lập phải miễn cưỡng ứng phó trong tình trạng pháp lực bị tiêu hao dữ dội."},{"chuong":1311,"tieuDe":"Thuyền Kim Đình Và Thiên Uyên Vệ","tomTat":"Sau khi chịu liên tiếp mười ba lôi cầu, Hàn Lập đã hao hơn phân nửa pháp lực nhưng lưỡng sắc lôi kiếp vẫn chưa dừng, trong khi nhiều thủ đoạn bảo mệnh không thể sử dụng hoặc đã bị hủy. Đúng lúc hắn chuẩn bị vận dụng phương tiện cuối cùng, một quang trận trắng ngà xuất hiện và truyền tống Thuyền Kim Đình cùng hai tu sĩ Luyện Hư mặc kim giáp tới. Hỏa lão nhận ra họ là Thiên Uyên Vệ, đồng thời xác định Hàn Lập vì chưa dùng Diệt Trần Đan nên dẫn phát loại Tiểu Thiên Kiếp nguy hiểm. Hai Thiên Uyên Vệ dùng ba phù triện tạo người khổng lồ lôi điện, thanh trùy xanh và búa vàng, phối hợp phóng tam sắc lôi quang đánh tan kiếp vân. Hàn Lập thu Nguyên Từ Thần Quang cùng Nguyên Từ Sơn rồi thận trọng tiếp xúc với hai người vừa cứu mình. Họ nhận ra hắn là tu sĩ phi thăng gặp không gian phong bạo nên không xuất hiện tại Phi Linh Thai, sau đó yêu cầu hắn đi theo tới Thiên Uyên Thành để thực hiện nghĩa vụ dành cho tu sĩ phi thăng."},{"chuong":1312,"tieuDe":"Thanh Minh Vệ","tomTat":"Hai Kim Giáp tu sĩ cho Hàn Lập biết hơi thở hạ giới sẽ khiến hắn phải chịu lưỡng sắc Lôi Kiếp theo chu kỳ ba trăm năm, và lần thiên kiếp kế tiếp sau hơn một trăm năm sẽ còn mạnh hơn trước. Muốn hóa giải mối họa này, hắn phải dùng mỗi năm một viên Diệt Trần Đan suốt ba trăm năm, nhưng muốn nhận đan từ Thiên Uyên Thành thì phải bỏ công sức làm nhiệm vụ đổi lấy. Không còn lựa chọn tốt hơn, Hàn Lập bước lên Kim Thuyền và cùng hai người rời đi bằng trận pháp truyền tống. Sau đó, Hỏa lão tiết lộ Thiên Uyên Thành là thế lực độc lập với Tam Thánh Hoàng và Thất Yêu Vương, còn Thiên Uyên Vệ có quyền tiêu diệt mọi đối tượng bị xem là mối đe dọa đối với nhân yêu lưỡng tộc. Trải qua khoảng hai mươi lần truyền tống đường dài với lượng lớn cao giai linh thạch bị tiêu hao, Hàn Lập cuối cùng đến một cơ sở phòng vệ nghiêm mật của Thiên Uyên Thành. Hai Kim Giáp tu sĩ giao hắn cho một đại hán mắt xanh dẫn tới Phi Linh Điện, đồng thời cho biết hắn sẽ bổ sung vào Thanh Minh Vệ và thậm chí có thể trở thành đội trưởng. Khi đi sâu vào thông đạo đá đen bị Ngân Khoa Văn phong tỏa thần niệm, Hàn Lập nhận ra các Hắc Giáp tu sĩ và Thanh Minh Vệ nơi đây đều có hàng ngũ chỉnh tề, rõ ràng đã được huấn luyện vô cùng nghiêm ngặt."},{"chuong":1313,"tieuDe":"Thiên Uyên Thành Và Phi Thăng Tu Sĩ","tomTat":"Hàn Lập theo Trác hiền chất đi sâu vào lòng đất, chứng kiến quần thể hơn trăm cự tháp đồ sộ của Thiên Uyên Thành rồi được đưa tới tầng bốn Phi Long Điện. Sau khi được giới thiệu là phi thăng tu sĩ do Thiên Vệ đại nhân mang về, hắn nhận một gian phòng rộng như động phủ cùng ngân bài điều khiển cấm chế. Hàn Lập nhận ra Dị Giới Hơi Thở đã làm đảo lộn kế hoạch tìm nơi ẩn tu tới Luyện Hư kỳ, nên quyết định tìm hiểu cách Thiên Uyên Thành an bài người mới phi thăng. Liễu Hà Đạo chủ động tới thăm, nhưng Hàn Lập thận trọng không tiết lộ nhân giới xuất thân vì e ngại những mối liên hệ cũ tại Linh giới. Liễu Hà Đạo cho biết phi thăng tu sĩ có tiềm lực tiến vào Luyện Hư kỳ cao, được miễn khảo hạch và do Trưởng Lão hội trực tiếp bổ nhiệm làm Thanh Minh Vệ. Ông còn giải thích rằng Dị Giới Hơi Thở phải được thanh trừ bằng Diệt Trần Đan trong khoảng ba trăm năm và có thể truyền tới hậu duệ trước đời thứ năm. Dù đã tẩy sạch loại hơi thở này, nhiều phi thăng tu sĩ cùng hậu duệ vẫn không muốn rời Thiên Uyên Thành vì tốc độ tu luyện cao và nguồn tài nguyên đặc biệt phong phú."},{"chuong":1314,"tieuDe":"Triệu Vô Quy","tomTat":"Lão giả họ Liễu giải thích cho Hàn Lập rằng Thiên Uyên Thành vừa là nơi hội tụ linh khí, kỳ trân và thần dược, vừa là cửa ngõ sống còn ngăn ngoại tộc tiến vào lãnh thổ Yêu Nhân lưỡng tộc. Thành có mười trưởng lão Hợp Thể kỳ, một siêu cấp tiên trận và chế độ giảng đạo định kỳ, nhưng mỗi lần ngoại tộc xâm lấn đều có thể gây thương vong cực lớn. Khi nghe số phi thăng tu sĩ tại Phi Linh Thai ngày càng giảm, Hàn Lập nhớ tới Cổ Ma nhưng che giấu và khẳng định nhân giới của mình không có gì khác thường. Lão giả cũng trình bày hai con đường làm vệ sĩ, gồm công việc cố định an toàn với thù lao thấp và nhiệm vụ đặc thù nguy hiểm nhưng có phần thưởng lớn. Sau cuộc trò chuyện, ông báo với nhóm tu sĩ Hóa Thần rằng Hàn Lập nói năng kín kẽ, còn nhóm này khẳng định chỉ muốn giao hảo với một phi thăng tu sĩ có tiềm lực. Sáng hôm sau, tu sĩ Luyện Hư kỳ Triệu Vô Quy tới gặp Hàn Lập, bổ nhiệm hắn làm Thanh Minh Vệ và giao quyền tiếp quản tiểu đội số năm mươi sáu. Hàn Lập nhận lệnh bài thân phận, bản đồ Thiên Uyên Thành và chỉ dẫn tới Ngọc Khuyết Các lo việc xây động phủ, đồng thời được miễn nhiệm vụ trong tháng đầu trước khi chính thức nhậm chức."},{"chuong":1315,"tieuDe":"Ngọc Khuyết Các","tomTat":"Hàn Lập đọc ngọc giản bản đồ, nhận ra Thiên Uyên Thành có quy mô không kém Thiên Nguyên Thành rồi tới Ngọc Khuyết Các tìm động phủ. Trên đường, hắn quan sát các cự tháp và suy ra giáp sĩ trong thành được phân tầng theo màu chiến giáp cùng cấp chiến lực. Tại tầng một Ngọc Khuyết Các, hắn chứng kiến các tu sĩ Nguyên Anh giao tài vật để được xét quyền chọn linh địa, qua đó hiểu rằng động phủ thích hợp phải tranh giành mới có được. Một nữ tu Trúc Cơ dùng Linh Áp Bàn nhận ra hắn là tu sĩ Hóa Thần và hướng dẫn hắn lên tầng hai. Khả năng dò xét của pháp bàn cùng kỹ nghệ luyện khí, trận pháp tại đây khiến Hàn Lập quyết định học lại kiến thức Linh giới để đề phòng những thủ đoạn xa lạ. Tại tầng hai, thị nữ giới thiệu ưu và nhược điểm của Thúy Lang Sơn, Yêu Vận Sơn cùng Quỳnh Thiên Sơn. Cuối chương, một tu sĩ mập mạp dâng Ngân Tiên Chi gần bốn ngàn năm tuổi và được Tử bào đại hán chấp nhận có đủ tư cách tranh linh địa."},{"chuong":1316,"tieuDe":"Tranh Giành Linh Địa","tomTat":"Trong đợt tuyển chọn động phủ tại Thiên Uyên Thành, Kim huynh chọn Thúy Lang Sơn, khiến nhiều tu sĩ khác phải thay đổi dự tính, còn hai người kế tiếp lần lượt chọn các mảnh đất tại Thiên Vận Sơn. Hàn Lập được miễn cống nạp vì là tu sĩ mới phi thăng và cố ý chọn một vùng rộng hơn hai vạn dặm nhưng linh khí loãng, tài nguyên nghèo để tránh tranh chấp. Tiêu sư thúc xác nhận lựa chọn này sẽ bị cố định trong năm trăm năm và người thất bại không thể lập tức chọn lại. Hán tử họ Ông sau đó xuất hiện, tiết lộ bí thuật mới cần một vùng tu luyện đủ rộng và phát hiện nơi mình nhắm tới đã bị Hàn Lập chọn. Trong lúc trò chuyện, mọi người cũng biết Minh lão quái đã vượt sáu lần đại thiên kiếp, mất Linh bảo cũ và đang bế quan tế luyện kiện mới cho lần vượt kiếp thứ bảy. Dựa vào ưu thế Hóa Thần trung kỳ, Hán tử họ Ông công khai ép Hàn Lập nhường đất và đe dọa đánh rớt cảnh giới của hắn. Vì cần động phủ để bồi dưỡng linh thảo và luyện chế đan dược, Hàn Lập bình thản từ chối, đồng thời cảnh cáo ngược rằng chính đối phương có thể bị hắn lỡ tay gây thương tích, khiến tất cả tu sĩ tại trường sửng sốt."},{"chuong":1317,"tieuDe":"Rước Lấy Phiền Toái","tomTat":"Hàn Lập không tiếp tục nhún nhường mà công khai nhận lời đấu với Hán tử họ Ông sau ba ngày để tranh quyền sở hữu linh địa. Sau khi Hàn Lập rời đi, Kim huynh bí mật dò xét họ Ông, khuyên hắn không nên giết một phi thăng tu sĩ nhưng đồng thời bị đối phương khơi ra chuyện mình vừa có được một Thượng cổ bảo vật. Phỉ thúy Giao long, phân thân sư phụ họ Ông, sau đó hiện thân và tiết lộ linh địa có thể là nơi một nhân vật bí ẩn tọa hóa, để lại di bảo cùng công pháp hữu ích cho việc độ kiếp và tiến giai Luyện Hư. Vì lợi ích này, nó ra lệnh cho đồ đệ phải thắng, cho phép hạ sát Hàn Lập và giao Thiên Hồn Linh để tế luyện tạm thời. Không biết mình đã bị đặt vào sát cục, Hàn Lập bay qua Thiên Uyên Thành để quan sát địa thế và suy tính. Thành trì có quy mô tương đương một tiểu quốc, được bảo vệ bởi tường thành, tiên trận, cấm chế cùng hơn trăm vạn quân nhân–yêu. Hai tộc liên thủ nhưng vẫn phân khu tự quản, còn hơn mười trưởng lão Hợp Thể kỳ cùng nghị sự tại tòa tháp trung tâm và tạo thành chiến lực cuối cùng của thành."},{"chuong":1318,"tieuDe":"Báo Lân Thú","tomTat":"Hàn Lập quan sát Trưởng Lão tháp và quyết định trước tiên gột sạch khí tức dị giới, sau đó lưu lại Thiên Uyên thành để chờ cơ hội thỉnh giáo tu sĩ Hợp Thể kỳ. Trở về mật thất tại Phi Linh Điện, hắn lấy con báo biến dị từng bị Linh tộc bắt tại Lạc Nhật chi mộ ra khỏi Linh Thú hoàn và từ ký ức của Phệ Viêm xác định nó là Báo Lân Thú mang một phần huyết mạch kỳ lân. Tiểu thú đã chịu khuất phục sau hơn mười năm bị giam, vì vậy Hàn Lập dùng ngân châm, máu, phù lục và lực lượng Nguyên Anh đặt cấm chế rồi tháo xích cho nó. Ba ngày sau, hắn nhận truyền âm phù của Ngọc Khuyết các và mang Báo Lân Thú đã thuần phục tới Nghiễm Vũ điện dự cuộc tranh đoạt linh địa. Hán tử họ Ông đến sát hạn vì bận tế luyện pháp bảo, còn kim giáp tu sĩ mặt sẹo công bố rằng hai bên có thể dùng mọi thủ đoạn cho tới khi một người rời phạm vi cấm chế hoặc nhận thua. Khi trận đấu bắt đầu, Hàn Lập tế bảy mươi hai khẩu phi kiếm hóa thành kim liên và phóng lớn Hư Thiên Đỉnh, trong khi đối thủ vận lam quang rồi tế Đoạn Tâm Pháp Luân. Khí thế của cự đỉnh khiến hán tử họ Ông lập tức sinh lòng kiêng kỵ."},{"chuong":1319,"tieuDe":"Thiên Hồn Linh","tomTat":"Hán tử họ Ông biến Lam Tinh Sa thành biển vân sa, giấu Đoạn Tâm Pháp Luân bên trong để tấn công Hàn Lập, nhưng bảy mươi hai đóa kim liên không những cản được thế công mà còn nghiền nát ngân luân. Hàn Lập thúc giục Hư Thiên Đỉnh phóng thanh hà cưỡng thu linh sa, đồng thời dùng Tịch Tà Thần Lôi đánh tan quỷ đầu được đối thủ gọi ra bằng máu. Khi Lam Tinh Sa hóa thành những khối nham thạch xanh biếc để chống cự, Hàn Lập thi triển Nguyên Từ Thần Quang khiến chúng trở lại hình dạng cũ rồi quét sạch toàn bộ sa vân. Dù chiếm ưu thế, hắn vẫn chưa nổi sát tâm vì chưa rõ lai lịch đối phương và còn kiêng dè vị sư phụ Luyện Hư kỳ đứng sau. Hán tử họ Ông tiếp tục gọi ra khôi lỗi cự hán màu xanh, hắc sắc cự lang và cho Nguyên Anh xuất khiếu mang theo Thiên Hồn Linh. Kim giáp tu sĩ nhận ra linh bảo của Minh lão quái, cảnh báo rằng việc cưỡng ép sử dụng sẽ khiến nguyên khí đại thương, nhưng hán tử họ Ông vẫn chấp nhận hậu quả và phát động đợt hợp kích mới."},{"chuong":1320,"tieuDe":"Uy Lực Luyện Thể","tomTat":"Hán tử họ Ông thúc động Thiên Hồn Linh công kích thần thức, khiến Hàn Lập choáng váng, nhưng Đại Diễn Quyết tự vận hành hóa giải âm ba và giúp hắn phản kích bằng Kinh Thần Thứ. Trong lúc Kim liên vây Thiên Hồn Linh rồi bị hắc ti áp chế, Khôi lỗi cự hán màu xanh liên tục dùng cự lực công kích Hư Thiên Đỉnh. Hắc lang do phù triện hóa thành xuyên qua Nguyên Từ Thần Quang để đánh lén, song Hàn Lập dùng La Yên Bộ áp sát, phát huy thần lực bẻ đầu ma vật và gọi Ngân hỏa điểu thiêu nuốt toàn bộ hắc vụ. Hắn thu được Ngân sắc phù triện đã hao tổn hơn phân nửa uy thế, sau đó vận dụng kiến thức Khôi Lỗi Thuật để tìm ra điểm yếu dưới sườn và phá hủy khôi lỗi. Hán tử họ Ông nhận ra Hàn Lập đã luyện Kim Cương bí quyết đến đại thành, đạt trình độ Luyện Thể sĩ đỉnh cấp và còn là người pháp thể song tu. Không chịu nhận thua, gã tiếp tục xuất Nguyên Anh, truyền lam sắc quang trụ vào Thiên Hồn Linh và niệm chú kích phát uy lực chân chính của linh bảo. Tiếng chuông cuối cùng gây dao động không gian dữ dội, mở ra một khe hở đen kịt trên không trung."},{"chuong":1321,"tieuDe":"Đoạt Được Linh Địa","tomTat":"Hán tử họ Ông phát động Thiên Hồn Linh, dùng hắc sắc pháp trận hút Hàn Lập cùng Cự Đỉnh và Kim liên vào không gian chứa hàng ngàn tinh hồn yêu thú. Dù nơi đó có cấm chế hạn chế pháp lực, Hàn Lập vẫn tiêu diệt hoặc vô hiệu hóa Chủ hồn, phá thủng không gian linh bảo và trở lại đấu trường. Hắn bất ngờ tập kích, phá tan khiên bạc rồi đánh lõm Thanh Minh Giáp, khiến đối thủ chịu nội thương nặng và buộc phải nhận thua. Hàn Lập vẫn dùng Thanh Trúc Phong Vân Kiếm chém xuống, nhưng Kim Giáp tu sĩ mặt sẹo kịp chuyển hán tử họ Ông khỏi phạm vi kiếm khí. Người chủ trì tuyên bố Hàn Lập chiến thắng và rót dấu hiệu sở hữu toàn bộ linh địa vào Thanh Minh Bội, đồng thời cho biết hắn không thể dự kỳ tranh đoạt trăm năm tiếp theo nếu chưa từ bỏ nơi này. Sau khi rời đấu trường với vẻ oán hận, hán tử họ Ông gặp Phỉ Thúy Giao Long và bị hỏi thẳng về thất bại cùng thương thế."},{"chuong":1322,"tieuDe":"Động Phủ","tomTat":"Hán tử họ Ông trở về phục mệnh, thừa nhận đã thất bại trước Hàn Lập và giao trả Thiên Hồn Linh bị tổn hại nghiêm trọng. Minh lão ma từ đó nhận định Hàn Lập đang đi theo con đường pháp thể song tu, đồng thời suy đoán hắn có bảo vật hoặc thần thông khắc chế âm hồn. Vì không muốn bỏ qua di bảo của một vị tiền bối trong linh địa, Minh lão ma sai đệ tử lấy tín vật rồi tìm Công Dương Kĩ mượn Mê Thiên Ngũ Sắc Phiên để chuẩn bị bí mật xâm nhập. Trong khi đó, Hàn Lập tới Quỳnh Thiên Sơn, khảo sát linh địa rộng hơn hai vạn dặm và cắm pháp kỳ xác lập ranh giới. Không tìm thấy điều gì đủ đặc biệt để giải thích cuộc tranh đoạt trước đó, hắn nhận ra linh địa có thể ẩn chứa bí mật và quyết định tiếp tục điều tra. Hàn Lập chọn một thạch cốc được chướng khí che phủ, xây hai động phủ thật và giả rồi bố trí dược viên, Trùng Thất cùng các thú thất. Cuối chương, hắn mở Linh Thú Hoàn trong một thú thất âm u và thả ra một con vật đen tuyền cao hơn một trượng chưa rõ thân phận."},{"chuong":1323,"tieuDe":"Huyền Thiên Linh Quả","tomTat":"Hàn Lập nhớ lại trận chiến trong không gian âm hồn, nơi hắn dùng Phong Lôi Sí và Ích Tà Thần Lôi đánh thương Quỷ Vương để Đề Hồn Thú hút sạch đối phương. Nhờ thôn phệ nhiều hung hồn cùng một Quỷ Vương có thực lực tương đương Hóa Thần, Đề Hồn Thú phá vỡ bình cảnh và hóa thành kén đen để tiến hóa. Trở lại động phủ, Hàn Lập phát hiện Huyền Thiên Tiên Đằng cùng toàn bộ linh căn chiết ra đều đã héo chết sau lần ra hoa kết quả tại Nhân giới. Hắn lấy Huyền Thiên Linh Quả khỏi hộp ngọc và nhận thấy nó đã biến thành một cây gậy gỗ ngắn có hoa văn xanh, bài xích linh lực và tự phục hồi sau khi bị biến dạng. Trong hơn mười ngày, kiếm ti, thần lôi, linh hỏa, Phệ Kim Trùng, nhiều loại công kích, Phá Diệt Pháp Mục và các tiểu trận đều không thể làm tổn hại hay tế luyện linh quả. Linh mục của hắn chỉ nhìn thấy một điểm sáng trắng ngà nhỏ bên trong vật này. Sau khi kiềm chế sự nóng vội, tâm cảnh Hàn Lập tiến thêm một bước, đồng thời hắn chợt nhận ra hoa văn trên linh quả giống một vật khác từng biết."},{"chuong":1324,"tieuDe":"Hỗn Độn Vạn Linh Bảng","tomTat":"Hàn Lập nhận thấy hoa văn trên chiếc bình thần bí có nét tương đồng với Huyền Thiên Linh Quả nên nhỏ một giọt lục dịch lên linh quả để thử nghiệm. Lục dịch thẩm thấu vào bên trong, dung nhập với điểm bạch quang và khiến quang điểm lớn thêm, đồng thời làm Hỗn Độn Vạn Linh Bảng tại Thiên Linh Cảnh phát sinh biến động. Danh xưng Huyền Thiên Trảm Linh Kiếm xuất hiện ở hạng ba, khiến các tu sĩ chứng kiến kinh hãi và lo ngại Chân Linh Kiếp. Những bảng tương tự tại Man Hoang Chi Địa và cấm địa của các Dị tộc cũng truyền tin mới, thúc đẩy lãnh đạo nhiều tộc bí mật truyền lệnh và tăng cường phòng thủ. Hàn Lập không biết mình là nguồn cơn của phong ba, tiếp tục ở lại động phủ cho tới khi phát hiện Đề Hồn đã phá kén. Đề Hồn hóa thành một nhân ảnh mặc hắc bào giống hệt Hàn Lập, mở linh trí và bắt đầu nói chuyện nhưng cũng thể hiện sự kháng cự với Minh Hồn Châu. Sau khi áp chế Đề Hồn, Hàn Lập gọi Nguyên Anh thứ hai ra và cho nó nhập vào cơ thể linh thú, khiến Đề Hồn bị hắc sắc điện quang bao phủ trong đau đớn."},{"chuong":1325,"tieuDe":"Thủ Hạ","tomTat":"Hàn Lập điều khiển đệ nhị Nguyên Anh dung nhập công pháp vào thần thức Đề Hồn, giúp linh thú hiểu lời và có thể trả lời, nhưng khiến Nguyên Anh tổn thương nguyên khí. Đề Hồn xác nhận đã mô phỏng hình dáng chủ nhân khi Hóa Hình, rồi lần lượt biến thành Cự Viên đen và ác quỷ ba sừng có ba xương gai lạ sau lưng. Sau khi thu Đề Hồn lại, Hàn Lập kiểm tra tiểu bình xanh biếc và phát hiện tại Linh giới nó chỉ mất ba ngày để tạo một giọt linh dịch, đồng thời dị tượng ánh trăng cũng trở nên mờ nhạt hơn. Vì dè chừng chủ cũ của linh địa, hắn mang theo Phệ Kim Trùng, Báo Lân Thú cùng các vật quan trọng rồi trở về Thiên Uyên Thành. Hàn Lập lĩnh Thanh Minh Giáp tại Thiên Giáp Điện, dùng ngọc bội mở đại điện Bính năm mươi sáu và được Trác Trùng cùng Đông Quách Phong ra mắt với tư cách đội trưởng mới. Khi Trác Trùng đang báo cáo về nhân sự và nhiệm vụ tuần tra, một kim kiếm truyền thư bay tới. Mã đạo trưởng sau đó trở về đại điện, cung kính tham kiến Hàn Lập và được hắn nhận ra đã đạt Nguyên Anh hậu kỳ đại thành."},{"chuong":1326,"tieuDe":"Phù Lê Chiểu Trạch","tomTat":"Hàn Lập nhận lệnh dẫn đội tuần tra Phù Lê Chiểu Trạch, khu vực nguy hiểm nhất quanh Thiên Uyên Thành và là nơi nhiều dị tộc thường ẩn hiện. Đông Quách Phong kể rằng Hiên Nghiễm, một tu sĩ Hóa Thần trung kỳ, từng cùng hai đồng đạo bị Ảnh Tộc đánh lén giết chết tại khu vực này. Các đội viên tỏ ra lo lắng, nhưng Hàn Lập vẫn bình tĩnh yêu cầu mọi người chuẩn bị và dành đêm tu luyện trong mật thất. Sáng hôm sau, Hứa tiên tử xuất hiện với thân phận hậu duệ dòng chính của tu sĩ phi thăng, khiến Hàn Lập cảm thấy nàng có phần quen thuộc. Cả đội dùng Truyền Tống Trận rời Thiên Uyên Thành, từ thạch thất trung chuyển tiến vào Man Hoang cổ giới rồi bay khoảng vạn dặm đến mục tiêu. Trước màn mê vụ của Phù Lê Chiểu Trạch, họ kích hoạt Dị Linh Bàn để dò xét dị tộc và thận trọng tiến sâu vào thủy vụ."},{"chuong":1327,"tieuDe":"Cự Thú, Quái Nhân","tomTat":"Đội tuần tra tiến sâu vào Phù Lê Chiểu Trạch, nơi thần niệm bị hạn chế, mê vụ tạo huyễn tượng và nhiều cổ thú nguy hiểm ẩn náu. Khi hàng trăm Khuê Trùng tràn ra, Hàn Lập dùng Nguyên Từ Thần Quang giữ chúng trên không rồi lấy thanh linh hỏa thiêu sạch, khiến các đội viên thêm tin phục. Sau hơn hai mươi ngày không phát hiện dị tộc, cả đội dừng chân tại một bờ thủy đàm có bãi đá và Thúy trúc, nhưng Hàn Lập nhận ra cảnh vật yên tĩnh một cách bất thường. Hắn âm thầm bố trí hồng ti rồi chém một cây trúc, qua đó vạch trần bãi đá là đầu của cự thú khổng lồ còn rừng trúc là những xúc tu ngụy trang. Cả đội đồng loạt công kích, song các xúc tu cứng chắc đánh bật nhiều bảo vật, còn lôi hỏa của Doanh thiếu niên và Hứa tiên tử bị một cơn lốc quái dị cuốn sạch. Cuối cùng, một quái nhân da lục nhạt hiện thân trên cự thú với phần cơ thể từ bắp đùi trở xuống nhập hoàn toàn vào thân con vật."},{"chuong":1328,"tieuDe":"Man Thú Nhân","tomTat":"Mã đạo trưởng nhận ra lục sắc quái nhân là Man thú nhân và thúc giục đồng đội tiêu diệt hắn trước khi thần thông nhân thú hợp nhất được thi triển, nhưng đợt vây công bị hoàng sắc cụ phong cùng nhục tu hóa giải. Trong lúc quan sát trận chiến, Hàn Lập phát hiện thủy đàm và đàn cá bạc thực chất là một cự thú trong suốt đang ngụy trang, nên dùng Nguyên Từ Thần Quang trói nó rồi lấy Nguyên Từ Thần Sơn trấn áp. Lục sắc quái nhân sau đó nhập vào cự thú của mình, hóa thành cự nhân hắc lân cao hơn mười trượng và phá nát nhiều pháp bảo đang vây công. Hứa tiên tử dùng bổn mạng phi kiếm hóa thành Băng Kiếm tập kích nhưng bị cự nhân khống chế, khiến nàng đứng trước nguy cơ tổn thương tâm thần. Hàn Lập ra tay giải vây, dùng hồng ti hóa thành hỏa tác trói chân đối phương rồi phóng Phệ Linh Thiên Hỏa thiêu Man thú nhân sau hợp thể thành hư vô. Cuối cùng, hắn ra lệnh bắt sống cự thú trong suốt và giao cho Dị Linh Đường xử lý, còn Trác Trùng lấy bạch sắc hồ lô khắc Ngân Khoa Văn để thu giữ nó."},{"chuong":1329,"tieuDe":"Thiên Uyên Phường Thị","tomTat":"Trác Trùng dùng hồ lô phối hợp với Nguyên Từ Thần Sơn của Hàn Lập để thu phục cự thú trong suốt, khiến các thành viên trong đội thực sự kính phục vị đội trưởng mới. Qua cuộc trò chuyện với Hứa tiên tử, Hàn Lập biết nàng là hậu duệ của Băng Phách Tiên Tử, người từng để lại nhiều cơ duyên cực hàn tại Nhân Giới. Hắn tặng nàng bốn khối Vạn Niên Huyền Ngọc để tái luyện Băng Tinh Kiếm, vừa trả lại phần tình xưa vừa giảm sơ hở tâm cảnh trước lần Độ Kiếp kế tiếp. Đội tuần tra sau đó trở về Thiên Uyên Thành bằng Kim Đình Chu, giao Man Thú cho Dị Linh Đường và nhận thưởng, riêng Hàn Lập được cấp Diệt Trần Đan rồi uống ngay tại chỗ. Hứa tiên tử báo cho hắn biết cuộc đấu giá vật phẩm Man Hoang sẽ diễn ra sau hai ngày, khiến hắn quyết định tới xem để tìm tài nguyên phục vụ tu luyện. Tại Thiên Uyên Phường Thị, Hàn Lập tìm đến một dược điếm và hỏi mua phương thuốc hoặc linh dược tăng tiến tu vi Hóa Thần. Chưởng quỹ cho biết cửa hàng có hai phương thuốc lưu truyền nhưng không đủ tài liệu quý hiếm để phối chế, rồi vào hậu đường lấy chúng cho hắn xem."},{"chuong":1330,"tieuDe":"Chân Thiềm Dịch Và Ngọc Thanh Đan","tomTat":"Hàn Lập xem phương thuốc Ngọc Thanh Đan và Chân Thiềm Dịch, qua đó biết loại đầu thích hợp với Hóa Thần sơ kỳ còn loại sau có dược tính mạnh, chủ yếu dành cho Hóa Thần hậu kỳ. Hắn mua toàn bộ hàng tại dược điếm rồi đi qua nhiều cửa hàng khác, thu thêm phương thuốc, hạt giống và ấu thảo để chuẩn bị luyện đan bằng nguồn linh dịch từ tiểu bình. Do Bích Nhãn Chân Thiềm Cổ Thú Linh Huyết cực kỳ hiếm, Hàn Lập quyết định tham dự đấu giá đại hội và cải trang thành đại hán mặt đen để bán linh thảo lâu năm cho Hồi Sinh Đường, bổ sung số linh thạch đã hao hụt. Trong lúc khảo sát phù triện, hắn phát hiện Khôi Lỗi Phù có thể gọi người bị phong ấn ra làm khôi lỗi và nhớ rằng Kim Khuyết Ngọc Thư cũng ghi phương pháp chế tác loại phù này, vì vậy mua vật liệu về nghiên cứu. Sau đó Hàn Lập đến Thái Huyền Điện, nơi Nhân Tộc và Yêu Tộc trao đổi vật phẩm dưới sự quản chế của đại trận, Kim Vệ và Thanh Minh Vệ. Hắn nhận ngọc bội tạo bạch hà che thân, tiến vào đại sảnh có hơn trăm người giao dịch rồi tiếp cận quầy của một tu sĩ Nhân Tộc. Tại đó, Hàn Lập nhìn thấy một vật giống cành cây xanh nhạt và một khối tinh thạch đỏ như máu nhưng chưa rõ lai lịch."},{"chuong":1331,"tieuDe":"Thiên Lôi Thành Mộc","tomTat":"Hàn Lập xem xét hàng hóa trong Thái Huyền Điện, nhận ra nhiều vật quý hiếm nhưng chưa có món nào đủ khiến hắn muốn giao dịch. Khi hắn định rời đi, một nữ tử Yêu Tộc che giấu dung mạo chủ động tiếp cận và giải thích rằng những vật thực sự có giá trị thường được trao đổi bí mật. Hàn Lập hỏi mua Chân Thiềm Thú Linh Huyết cùng các linh dược còn thiếu, rồi chuyển sang yêu cầu hạt giống hoặc ấu thảo khi biết thành phẩm quá khan hiếm. Hắn dùng khả năng cung cấp vạn năm linh dược làm điều kiện trao đổi và giao trước một gốc linh dược ba ngàn năm để tạo lòng tin, khiến nữ tử nhận lời dành vài năm tìm hai hoặc ba loại tài liệu. Trên đường rời đại sảnh, Hàn Lập dừng trước quầy của một lão giả Nhân Tộc và chú ý tới cành cây xanh biếc sinh ra sau khi thiên lôi đánh cháy cây mẹ. Cành linh mộc chứa lôi lực quá bá đạo để quán chủ hấp thu, luyện hóa hoặc dùng vào luyện khí, khiến Hàn Lập tỏ rõ hứng thú với Thiên Lôi Thành Mộc."},{"chuong":1332,"tieuDe":"Lôi Văn Thần Bí","tomTat":"Tại Thái Huyền Điện, Hàn Lập hỏi mua một cành lôi mộc do thiên lôi hình thành và biết lão giả bán vật này đang cần linh thảo năm nghìn năm để luyện Càn Nguyên Đan. Sau khi lão giải thích rằng thần thông khứu giác đã giúp mình nhận ra dấu vết linh dược lâu năm, Hàn Lập lấy một gốc linh dược phù hợp ra trao đổi rồi mang lôi mộc rời đi. Trở lại điện phủ trong cự tháp, hắn phong kín tĩnh thất và phát hiện lôi mộc chứa lực lôi điện cuồng bạo, ổn định nhưng bài xích linh lực. Nhờ Minh Thanh Linh Mục, Hàn Lập nhìn thấy vô số điện ti cực nhỏ đan theo quy luật thành những hoa văn phức tạp trong các mặt cắt của linh mộc. Hắn cắt cành cây thành nhiều đoạn và lát mỏng, quan sát những lôi văn khác nhau rồi lưu toàn bộ cảnh tượng vào ngọc giản. Sau một ngày đêm nghiên cứu, Hàn Lập dùng Tịch Tà Thần Lôi mô phỏng kết cấu lôi văn nhưng lần thử đầu tiên tan vỡ vì một sai sót điều khiển. Dù thất bại, hắn đã cảm nhận được một lực lượng vô danh trong kết cấu đang hình thành nên lập tức tiếp tục thử nghiệm với số điện ti lớn hơn."},{"chuong":1333,"tieuDe":"Kẻ Ác","tomTat":"Hàn Lập nhiều lần điều khiển điện ti theo kết cấu lôi điện và cuối cùng ngưng tụ thành Cẩm Mạt mang lôi văn thần bí. Khi được kích phát, lôi vật này hiển hóa hư ảnh lôi văn, phát ra linh áp khiến cấm chế thạch thất không thể chịu nổi; hắn sau đó tạo thêm Kim Châu nhưng nhận ra lực lượng bên trong hai vật có tính chất khác nhau. Những thử nghiệm tương tự với Phệ Linh Thiên Hỏa và thanh sắc linh ti đều thất bại, khiến Hàn Lập suy đoán lôi văn là phù văn thiên nhiên có liên hệ với tiên gia văn tự. Sau khi cất hai lôi vật và rời tĩnh thất, hắn phát hiện Hứa tiên tử cùng Trác Trùng đang bị Hoàng Bảo và đồ đệ gây sức ép trong đại sảnh. Hoàng Bảo vin vào một vụ đánh cược để ép Hứa tiên tử lấy đồ đệ mình, đồng thời đe dọa Hứa gia nếu nàng không thực hiện lời hứa. Vì biết nàng là hậu duệ của Băng Phách Tiên Tử, Hàn Lập đứng ra yêu cầu hai bên kiểm chứng lại cuộc đối đầu giữa Băng Tinh Kiếm và Lục Ba Nhận. Khi trung niên lùn phóng Lục Ba Nhận ra, Hàn Lập dùng Minh Thanh Linh Mục nhìn thấu bên trong có hai loại linh lực mạnh yếu khác nhau, xác nhận pháp bảo đã bị động tay chân."},{"chuong":1334,"tieuDe":"Thần Thông Tâm Hàn Nhập Thể","tomTat":"Hứa tiên tử gọi Băng Tinh Kiếm ra đối đầu Lục Ba Nhận, còn Hàn Lập tạm thời đoạt quyền điều khiển kiếm để quán Phệ Linh Thiên Hỏa vào trong. Khi nhận lại pháp bảo, nàng hóa kiếm thành ngân sắc hỏa điểu, áp đảo độc giác lục giao do Lục Ba Nhận biến thành và phong kín phi đao trong băng. Hàn Lập đồng thời bí mật thi triển Tâm Hàn Nhập Thể, truyền cực hàn chi lực qua mối liên hệ giữa bổn mạng pháp bảo và chủ nhân, khiến đồ đệ Hoàng Bảo đông cứng rồi hôn mê. Hoàng Bảo phá băng, thu hồi phi đao và dùng hồng dược hoàn cứu đồ đệ, sau đó thừa nhận không bằng Hàn Lập và từ bỏ chuyện cầu thân. Hàn Lập xác minh hai người chỉ xuất thân từ tiểu tông môn Lưu Sa Cốc rồi cảnh cáo Hứa tiên tử rằng mình sẽ không tiếp tục giải quyết những phiền phức tương tự cho nàng. Sau khi hắn rời đi, Hứa tiên tử tiết lộ mình có quan hệ với tổ tiên của Hàn Lập và ngăn Trác Trùng dò hỏi sâu về ngân diễm. Hàn Lập cuối cùng bay tới phường thị Thiên Uyên Thành để kịp tham dự đấu giá hội giữa trưa."},{"chuong":1335,"tieuDe":"Vật Đấu Giá Ngoài Ý Muốn","tomTat":"Hàn Lập dùng bí thuật biến thành một đại hán râu quai nón rồi tiến vào Thái Huyền Điện tham dự hội đấu giá. Sau khi giao linh thạch và nhận ngọc bội che giấu dung mạo, hắn được pháp trận truyền vào một Phi Thiên Thạch Ốc lơ lửng trong cự sảnh, nơi phù văn có thể ngăn thần niệm và bảo vệ thân phận người tham gia. Hội đấu giá nhanh chóng tập hợp mấy trăm tu sĩ ít nhất đạt Hóa Thần, trong đó còn có một số tu sĩ Luyện Hư. Xích đại sư xuất hiện với tư cách Luyện Khí Tông Sư giám định kiêm chủ trì, đồng thời bất ngờ công bố ba vật phẩm áp trục gồm tài liệu cực phẩm từ Man Hoang, một kiện Thông Thiên Linh Bảo có thứ hạng trong Hỗn Độn Vạn Linh Bảng và công pháp hoàn chỉnh của một tiền bối Hợp Thể kỳ đại thành. Vì tin tức được công bố muộn, hội đấu giá cho phép người mua dùng vật phẩm quý hiếm thay linh thạch sau khi được định giá. Ba bình Hoán Tâm Đan mở màn được bán với giá sáu mươi vạn linh thạch, còn Hàn Lập không tham gia tranh mua vì có thể tự luyện Ngọc Thanh Đan. Trong ba món áp trục, hắn chỉ tò mò về tài liệu Man Hoang và Thông Thiên Linh Bảo nhưng thực sự động tâm trước bí tịch chủ tu của tu sĩ Hợp Thể hậu kỳ."},{"chuong":1336,"tieuDe":"Đấu Giá","tomTat":"Thanh Nguyên Kiếm Quyết đã được luyện tới cực hạn, khiến Hàn Lập phải cân nhắc giữa chuyển sang một công pháp cao giai thông thường và đi theo con đường Pháp Thể Song Tu. Hắn xác nhận Minh Vương Quyết, Thác Thiên Ma Công và công pháp Phạm Thánh Chân Phiến có thể hỗ trợ nhau thành một hệ thống tuần tự, nhưng nguồn gốc của hai phần đầu bị khuyết vẫn chưa chắc chắn nên rủi ro rất lớn. Hàn Lập tạm hoãn lựa chọn để chờ xem di lưu công pháp của một tu sĩ Hợp Thể kỳ đại thành có phù hợp với mình hay không. Hội đấu giá lần lượt bán các đan dược tăng tiến tu vi, đan dược phụ trợ và nhiều pháp bảo, trong đó Độc Mãng Lệnh được bán với giá hai trăm ba mươi vạn linh thạch. Một Linh Bảo cấp thấp còn khiến cả tu sĩ Luyện Hư kỳ tham gia tranh đoạt vì có thể nâng cao khả năng vượt Đại Thiên Kiếp. Khi Chân Thiềm Linh Huyết được đưa ra với giá khởi điểm một trăm năm mươi vạn linh thạch, một người bí ẩn trong Phi Thiên Thạch Ốc khác bất ngờ trả thẳng ba trăm vạn. Mức giá này khiến cả đại sảnh im lặng, còn Hàn Lập trở nên âm trầm vì mục tiêu chính của hắn đang đứng trước nguy cơ rơi vào tay người khác."},{"chuong":1337,"tieuDe":"Chân Linh Lân Phiến","tomTat":"Hàn Lập từ bỏ tranh mua Chân Thiềm Linh Huyết vì lượng linh huyết không đủ luyện đan và việc bán thêm linh thảo lâu năm có thể khiến hắn bị chú ý; món linh huyết sau đó được bán với giá bốn trăm vạn linh thạch. Hội đấu giá tiếp tục bán nhiều tài liệu quý dành cho tu sĩ Luyện Hư với mức giá rất cao, rồi chuyển sang ba bảo vật trân quý cuối cùng do tam đại giám định sư phụ trách. Bảo vật đầu tiên là ba miếng lân phiến của Man Hoang Chân Linh Mặc Kỳ Lân, có thể dùng luyện Quỳ Thủy Chân Linh Đan hoặc Linh Bảo thủy thuộc tính cao cấp. Biết Quỳ Thủy Chân Linh Đan có thể giúp Hóa Thần sơ kỳ tiến lên trung kỳ, Hàn Lập quyết giành lân phiến bằng mọi giá. Trung niên phụ nhân trình diễn thủy linh lực tinh thuần của lân phiến rồi dùng Kim Phủ, Tam sắc Thanh Kiếp Hỏa, lôi kích, băng phong và huyết vụ ma đạo để kiểm nghiệm, nhưng tất cả đều không thể làm nó tổn hại. Ba miếng lân phiến được mở giá một ngàn năm trăm vạn linh thạch và nhanh chóng bị đẩy lên hai ngàn vạn, còn Hàn Lập vẫn chưa ra giá mà bình tĩnh quan sát."},{"chuong":1338,"tieuDe":"Chộp Được","tomTat":"Ba miếng Chân Linh Lân Phiến khiến các tu sĩ Hóa Thần tranh giá quyết liệt, nhưng phần lớn lần lượt rút lui khi mức giá đạt ba nghìn vạn linh thạch. Hàn Lập bất ngờ nhập cuộc, đối đầu với chủ nhân giọng nói lười biếng và giành được lân phiến với giá ba nghìn năm trăm vạn, bất chấp đối thủ công khai nghi ngờ khả năng thanh toán của hắn. Khi Xích đại sư cùng Hà đạo hữu vào Phi Thiên Thạch Ốc kiểm tra, Hàn Lập đưa ra một gốc Tuyết Giao Thảo mười vạn một ngàn năm cùng bốn gốc linh thảo lâu năm khác để hoàn tất giao dịch. Sau khi nhận ba miếng lân phiến, hắn đặc biệt tập trung quan sát miếng màu xanh. Phiên đấu giá tiếp tục với Bình Hải Qua, một Thông Thiên Linh Bảo được biểu diễn trước đám đông rồi bán cho tu sĩ xa lạ với giá ba nghìn năm trăm vạn linh thạch. Chương khép lại khi món đồ tối hậu của đại hội sắp được đưa ra."},{"chuong":1339,"tieuDe":"Chân Linh Thế Gia","tomTat":"Xích đại sư đưa bản gốc Âm Dương Hóa Cực Quyết do Ngũ Linh Chân Quân sáng tạo ra đấu giá, đồng thời công bố uy lực, nguồn gốc và những điều kiện tu luyện cực kỳ hà khắc của nó. Hàn Lập từ bỏ tranh mua vì giá cao, tỷ lệ thành công thấp và công pháp chưa chắc thích hợp hơn con đường Pháp Thể Song Tu của mình, còn nữ tu bí ẩn có giọng nói lười biếng trả bốn nghìn vạn để đoạt ngọc giản. Sau đại hội, Hàn Lập rời Thái Huyền Điện và trở về động phủ, dự định luyện Ngọc Thanh Đan nhưng tiếp tục giữ lại ba Chân Linh Lân Phiến cho tới khi xác minh chắc chắn phương pháp luyện Quỳ Thủy Linh Đan. Trong mật thất, Xích đại sư dùng Tử Quang Linh Mục xác định người mua công pháp là một nữ tu trẻ rồi báo cáo với công tử Lũng gia. Công tử tiết lộ cuộc đấu giá là cái bẫy do Lũng gia bố trí bằng Âm Dương Hóa Cực Quyết, Mặc Kỳ Lân Lân Phiến và Bình Hải Qua để dụ người kế thừa Thiên Phượng Huyết Mạch xuất hiện, đồng thời nghi nữ tu thuộc Diệp gia hoặc Cốc gia. Hai người cũng chú ý đến nguồn Vạn Năm Linh Thảo của Hàn Lập nhưng quyết định không truy xét vì chưa loại trừ khả năng hắn liên quan đến Nhuận gia hoặc Thiểm gia. Vài ngày sau, khi Hàn Lập sắp trở lại sơn mạch đặt động phủ, hai người chưa rõ danh tính đang căng thẳng giằng co tại nơi cách động phủ hơn nghìn dặm."},{"chuong":1340,"tieuDe":"Thiên Bảo Thượng Nhân Và Vạn Lung Châu","tomTat":"Hán tử họ Ông phát hiện Kim Bàn Tử đã dùng thuật ẩn nấp bám theo mình hơn mười vạn dặm tới linh địa của Hàn Lập, nơi hắn đang bí mật tìm kiếm một thứ quan trọng. Cuộc phục kích bằng lục sắc ti võng và lam sắc phi đao bị kim sắc đại thủ ngăn cản, khiến các hóa thân liên quan tới Kim lão quái và Minh lão ma lộ diện. Qua đối thoại, hai bên tiết lộ rằng họ cùng nhắm tới những bảo vật tùy thân của Thiên Bảo Thượng Nhân, nhưng mỗi bên chỉ nắm một phần đầu mối nên buộc phải tạm hợp tác. Trước khi Hàn Lập trở về, hai nhóm lần lượt dùng Tử Phong Tán và quạt nhỏ ngũ sắc rút khỏi linh địa. Hàn Lập vẫn nhận ra dao động linh khí còn sót lại nhờ thần thức được Đại Diễn Quyết tăng cường, song tìm kiếm quanh khu vực mà không phát hiện thủ phạm. Lo ngại có người tiếp tục xâm nhập, hắn tăng cường cấm chế rồi dành ba ngày ba đêm luyện chế pháp bàn bát giác cùng nhiều Vạn Lung Châu dựa trên tri thức từ Kim Khuyết Ngọc Thư. Hệ thống này có thể giám sát dao động linh khí trên phạm vi rộng, nhưng việc bao phủ toàn bộ linh địa đòi hỏi một siêu đại pháp trận và lượng linh thạch khổng lồ."},{"chuong":1341,"tieuDe":"Lôi Bào Hiện Thế","tomTat":"Nghi có người bí mật mưu đồ trong linh địa, Hàn Lập chôn một bộ Vạn Lung Châu trên gần hai phần ba khu vực rồi kết nối chúng với pháp trận và bát giác pháp bàn để giám sát. Trở lại mật thất, hắn nghiên cứu lôi văn, thử sức chịu đựng của kim sắc Cẩm Mạt và tiếp tục khảo nghiệm viên kim sắc châu chứa lôi điện cuồng bạo. Vụ nổ của viên châu phá vỡ cấm chế mật thất, nhưng Hàn Lập dùng hắc sắc tiểu sơn cùng Nguyên Từ Thần Quang khống chế lôi điện và xác định Lôi Văn Châu mạnh hơn Tịch Tà Thần Lôi trên mười lần. Do tỷ lệ ngưng tụ thấp, hắn vận dụng Thông Thiên Bảo Quyết lấy kim ngân lưỡng sắc thiên lôi trong Hư Thiên Đỉnh làm nguyên liệu thử nghiệm. Sau hơn nửa tháng, pháp trận phát hiện bốn mục tiêu tiến gần động phủ rồi phân tán và liên tục đổi vị trí, khiến Hàn Lập phái hơn mười nhóm Phệ Kim Trùng ra ngoài dò xét. Trong thời gian bế quan, hắn đã luyện thành Lôi Bào cô đọng hơn mười loại lôi điện phù văn cùng hơn mười viên Lôi Văn Châu, khiến thực lực tăng mạnh. Hoàn tất việc luyện chế, Hàn Lập lấy tàn trang Kim Khuyết Ngọc Thư ra để tiếp tục nghiên cứu."},{"chuong":1342,"tieuDe":"Dò Xét","tomTat":"Hàn Lập tổng kết tiến độ nghiên cứu bốn loại đạo phù trong Kim Khuyết Ngọc Thư, trong đó Thái Nhất Hóa Thanh Phù là loại hắn nắm chắc nhất, còn Giáp Nguyên Phù vừa được tìm ra điểm mấu chốt và Thiên Qua Phù vẫn vượt quá tạo nghệ hiện tại. Để tăng cường thủ đoạn bảo mệnh tại Thiên Uyên Thành, hắn dành hơn hai tháng luyện chế và thành công tạo ra một đạo Thái Nhất Hóa Thanh Phù hoàn chỉnh hơn bản từng sử dụng. Khi khởi động lại pháp trận giám sát, hắn phát hiện bốn tu sĩ xâm nhập đã tụ tập nhiều ngày tại một nơi cách động phủ khoảng bốn đến năm trăm dặm. Một số Phệ Kim Trùng làm nhiệm vụ trinh sát đã bị tiêu diệt, còn thần niệm thu hồi từ số sống sót cho hắn biết đối phương đang tìm một món đồ và có thể có tu sĩ Luyện Hư. Không muốn linh địa của mình bị cuốn vào biến cố, Hàn Lập quyết định đích thân bí mật dò xét và sẵn sàng tranh lợi nếu có cơ hội. Hắn lần lượt dùng thuật ẩn nấp, Thổ Độn Thuật và thủ đoạn thu liễm khí tức để tiếp cận khu vực mục tiêu. Cuối cùng, vì lo thần niệm của tu sĩ Luyện Hư phát hiện, hắn kích hoạt Thái Nhất Hóa Thanh Phù mới, hóa thành hư vô rồi tiếp tục tiến về phía trước."},{"chuong":1343,"tieuDe":"Không Gian Kỳ Bí","tomTat":"Hàn Lập bí mật bám theo bốn tu sĩ tới ngọn thạch sơn trơ trụi trong linh địa và dùng Minh Thanh Linh Mục phát hiện tám quang trụ đang duy trì một Tứ Phương Pháp Trận che giấu. Hắn vận dụng Thái Nhất Hóa Thanh Phù để hư hóa thân thể, xuyên qua cấm chế rồi lặn xuống lòng đất, nhưng bị thất sắc hào quang khóa chặt và truyền tống vào một không gian kỳ bí. Nhờ Kim Cương Quyết đã đại thành, hắn chịu được sức ép đủ sức nghiền nát tu sĩ bình thường và không bị trọng thương. Tại đây, Hàn Lập chạm mặt Kim Bàn Tử cùng Hán tử họ Ông và biết hai trưởng bối Luyện Hư của họ đã tiến sâu qua quang môn thất sắc. Khi hai người nảy ý định ra tay, hắn tuyên bố đã để lại Truyền Âm Phù cho các đạo hữu và Triệu Vô Quy, đồng thời viện dẫn Chấp Pháp Đội cùng luật lệ Thiên Uyên Thành để buộc họ dè chừng. Kim Bàn Tử phải chuyển sang hòa hoãn và đề nghị chờ các trưởng bối trở về thương lượng. Hàn Lập không rút lui mà khoanh chân ngồi lại, chủ động chờ gặp hai tu sĩ Luyện Hư."},{"chuong":1344,"tieuDe":"Ngọc Cốt Nhân Ma","tomTat":"Kim Bàn Tử và hán tử mày xếch án binh bất động trước Hàn Lập, còn Hàn Lập cũng tránh giao chiến để không kết thù với hai tu sĩ Luyện Hư phía sau quang môn. Khi dùng thần niệm dò vách không gian, hắn gặp lực hút nguy hiểm và phải vận chuyển Đại Diễn Quyết để cắt đứt liên hệ, sau đó chuyển sang Minh Thanh Linh Mục. Một ngày một đêm sau, bảy quang đoàn quanh quang môn phình lớn, thất sắc hào quang trên vách tan rã và toàn bộ không gian xuất hiện dấu hiệu sụp đổ. Kim lão quái cùng Minh lão ma trong hai hóa thân bị thương chạy khỏi quang môn, tiết lộ nơi đây là chỗ giam Ngọc Cốt Nhân Ma chứ không phải nơi Thiên Bảo Thượng Nhân tọa hóa. Chính việc họ chấn động cấm chế Thượng Cổ đã giải thoát ma vật và khiến không gian mất ổn định. Minh lão ma thoáng muốn giết Hàn Lập nhưng được Kim lão quái ngăn lại, rồi cả hai quyết định phá không gian đào thoát và bỏ mặc Hàn Lập táng thân cùng ma vật. Kim lão quái triệu Mộc Kiếm hóa thành cự đại kiếm quang, Minh lão ma hiện nguyên hình Lục Giao độc giác, trong khi Hàn Lập chuẩn bị Phá Diệt Pháp Mục, Nguyên Từ Thần Quang và ba viên Lôi Văn Châu để tự tìm đường sống."},{"chuong":1345,"tieuDe":"Không Gian Phong Bạo","tomTat":"Minh lão ma và Kim lão quái hợp lực phá chướng bích, tạo một thông đạo tạm thời để đưa những người đi cùng thoát khỏi không gian giam giữ. Hàn Lập dùng Hóa Linh Phù tạo thế thân, âm thầm vận dụng Phong Lôi Sí tiếp cận lối ra rồi lấy Nguyên Từ Thần Quang bám chặt vào độn quang của Kim lão quái. Trong lúc Ngọc Cốt Nhân Ma phát động Khấp huyết đại pháp và đưa hai cốt trảo qua quang môn, Hàn Lập ép Kim lão quái phải mang mình xuyên qua thông đạo. Ngay sau khi mọi người trở lại vùng trời phía trên thạch sơn, hư không quanh quang cầu xuất hiện những nếp gấp dày đặc và bùng phát thành không gian phong bạo. Các cơn lốc sinh ra từ hắc ti vỡ tung nghiền nát mọi vật, khiến tất cả phải dùng độn thuật thông thường chạy khỏi khu vực thay vì thuấn di. Nhớ lại lần suýt chết trong không gian tiết điểm, Hàn Lập không tiếp tục đối đầu với hai tu sĩ Luyện Hư mà lập tức trở về động phủ."},{"chuong":1346,"tieuDe":"Cốt Thủ","tomTat":"Kim lão quái muốn Minh lão ma truy sát Hàn Lập để tránh chuyện đoạt bảo bị tiết lộ, nhưng Minh lão ma nhìn thấu ý định mượn đao giết người và không muốn đắc tội với người có liên hệ cùng Triệu Vô Quy và Lôi La Chân Nhân. Hai nhóm tu sĩ Luyện Hư lần lượt rời khỏi linh địa, trong khi Hàn Lập tiếp tục dùng Vạn Lung Châu theo dõi cho đến khi không gian phong bạo biến mất. Một điểm sáng trắng xám bất ngờ xuất hiện và tiến về phía động phủ, khiến Hàn Lập chủ động truy tìm tới khu rừng cách đó hơn ba trăm dặm. Hắn dùng quang thủ và Hỏa Linh Ti bắt dị vật, luyện mất linh tính rồi nhận ra đó là bạch ngọc cốt thủ của Ngọc Cốt Nhân Ma. Trên ngón cái của cốt thủ còn gắn một trang Kim Khuyết Ngọc Thư hoàn chỉnh, dường như ghi chép về đạo luyện khí, nên Hàn Lập phong cấm và mang cả hai vật về động phủ. Không lâu sau, hai Thiên Vệ kim giáp đi Thuyền Kim Đình tới hiện trường, dùng Càn Khôn Bàn và thần niệm kiểm tra rồi kết luận đây chỉ là một đợt không gian phong bạo quy mô nhỏ."},{"chuong":1347,"tieuDe":"Bách Mạch Luyện Bảo Quyết","tomTat":"Hai Thiên Vệ cấp Luyện Hư dùng Càn Khôn Bàn và Dị Linh Bàn kiểm tra khu vực động phủ Hàn Lập, nhưng rời đi sau khi không phát hiện hơi thở dị tộc. Hàn Lập đóng pháp trận, ngừng Vạn Lung Châu rồi dùng Kim Sắc Tiểu Kiếm phá cốt thủ, lấy ra một ngọc bài thông linh khắc Ngân Khoa Văn. Sau ba ngày nghiên cứu, hắn lĩnh ngộ Bách Mạch Luyện Bảo Quyết, một bí thuật tế luyện xương cốt, kinh mạch và huyết nhục thành pháp bảo nhưng có yêu cầu thân thể cực cao. Phát hiện này giúp Hàn Lập quyết định theo con đường Pháp Thể Song Tu, kết hợp Thác Thiên Ma Công, Kim Cương Quyết và công pháp liên quan đến Phạm Thánh Chân Phiến. Hắn tiếp tục lĩnh hội ma công, luyện thành vài bình Ngọc Thanh Đan rồi luân phiên bế quan và tuần tra trong sáu mươi năm. Cùng thời gian đó, cao tầng nhiều tộc trong Linh Giới âm thầm tụ hội và truy tìm một vật chưa rõ, khiến Thiên Uyên Thành cảm nhận phong ba sắp tới. Tại Phù Lê Chiểu Trạch, một đội gồm một Thanh Minh Vệ Hóa Thần và mười Hắc Thiết Vệ phát hiện dấu hiệu dị tộc, đồng thời nhắc lại tổn thất nặng nề do Hư Động Tộc Nhân gây ra cho Tiểu đội số bốn."},{"chuong":1348,"tieuDe":"Lục Ảnh","tomTat":"Đội trưởng Hắc Thiết Vệ quyết định truy xét nơi Dị Linh Bàn phát cảnh báo vì bỏ qua nhiệm vụ sẽ khiến cả đội chịu trọng phạt. Tiểu đội dừng trên một bãi loạn thạch có bọt khí tím, nơi thần niệm không thể xuyên xuống, rồi cho Tần đạo hữu triển khai hơn một trăm khôi lỗi thiết phong dò đường. Dị Linh Bàn sau đó báo mục tiêu vô hình đã tiến vào phạm vi trăm trượng, nhưng đồng kính cùng nhiều bảo vật phá ẩn vẫn không thể tìm thấy đối phương. Điện võng cuối cùng ép một Lục Ảnh trung giai đỉnh phong hiện thân, song nó dùng lục sắc đại thủ thu sạch đợt lôi điện tiếp theo. Các ảnh khôi lỗi chia cắt và truy đuổi những Hắc Thiết Vệ ở xa, còn Lục Ảnh trực tiếp áp sát đội trưởng, xuyên qua lớp lôi điện hộ thân và giữ chặt tiểu kiếm phòng ngự. Đúng lúc đội trưởng lâm nguy, một bóng người có hai cánh xuất hiện trong hồ quang xanh trắng và lập tức vung cả hai tay xuống."},{"chuong":1349,"tieuDe":"Dị Tộc Nghi Vấn","tomTat":"Hàn Lập dùng Tứ Phương Cẩm Mạt, Ngũ sắc Hàn diễm và Nguyên Từ Thần Quang để áp chế các ảnh khôi lỗi cùng bản thể Lục Ảnh. Khi đối phương phân tán thành vô số lục ti tháo chạy, hắn dùng hôi sắc quang hà nghiền nát đường thoát rồi dán cấm chế phù, biến Lục Ảnh thành một viên cầu và bắt sống. Nhạc đạo hữu cùng các Hắc Thiết Vệ được cứu thoát nên cảm tạ và bày tỏ sự kính phục đối với chiến lực của Hàn Lập. Chương cũng xác nhận Hàn Lập đã tiến lên Hóa Thần trung kỳ và trong hơn mười năm tuần tra chưa để tiểu đội của mình mất một thành viên nào. Sau khi hội hợp với Trác Trùng, Mã đạo trưởng, Hứa tiên tử và các thuộc hạ, hắn trao đổi về việc cao giai Động Hư Tộc, Ảnh Tộc cùng nhiều thám tử liên tiếp xuất hiện. Tình hình bất thường tại Phù Lê Chiểu Trạch và Táng Cốt Sa Mạc khiến Mã đạo trưởng nghi ngờ Dị Tộc đang chuẩn bị tiến công Thiên Uyên Thành. Hứa tiên tử lại thấy điều này khó hiểu vì lần công thành trước mới cách khoảng ba vạn năm, ngắn hơn nhiều so với chu kỳ bảy, tám vạn năm thường được biết."},{"chuong":1350,"tieuDe":"Thiên Nghiễm Điện","tomTat":"Mã đạo sĩ kể lại hậu quả của Bách Tộc Đại Chiến và cảnh báo một biến cố trọng đại có thể khiến chiến tranh giữa các tộc tái diễn sớm, làm các thành viên đội tuần tra lo sợ. Hàn Lập giữ bình tĩnh, yêu cầu mọi người hoàn thành nhiệm vụ rồi dẫn đội trở về Thiên Uyên Thành bằng Kim Đình Chu. Tại tầng thứ mười của cự tháp, hắn giao ngọc hạp chứa Lục Ảnh cao giai cho Văn tiền bối và được xác nhận đã lập công đáng kể. Hàn Lập dùng công trạng này cùng thành tích trước đó để xin tư cách vào Thiên Nghiễm Điện nghe Hình trưởng lão giảng Phù Lê Chi Thuật, bất chấp lời khuyên nên tập trung tăng tiến tu vi. Sau khi được cấp ngọc bài công trạng, hắn tới Thái Huyền Điện tại Thiên Trắc Giảm phường thị và gặp Viêm đạo hữu. Hai người đối chiếu những dấu hiệu bất thường trong thành, gồm số thám tử dị tộc, tu sĩ cao giai và người mới từ Thất Địa đồng loạt gia tăng, từ đó nhận định nguy cơ dị tộc công thành không hề thấp. Viêm đạo hữu quyết định đây là lần giao dịch cuối, khuyên Hàn Lập tìm cách rời Thiên Uyên Thành, còn hắn thừa nhận thân phận hiện tại khiến việc thoát thân không dễ dàng."},{"chuong":1351,"tieuDe":"Tụ Hội","tomTat":"Hàn Lập gặp lại nữ tử Yêu Tộc trong hắc khí tại Thái Huyền Điện và dùng nhiều gốc linh dược vạn năm đổi lấy một hộp chứa phần lớn số hạt giống đã yêu cầu. Sau khi kiểm tra kỹ vật trao đổi, hắn xác nhận trong số đó có hai loại rất hữu dụng cho Hóa Thần trung kỳ, còn nữ tử dự định dùng linh dược nhận được để luyện đan phá bình cảnh. Hàn Lập xem qua các quầy hàng của Nhân Tộc và Yêu Tộc nhưng không tìm thấy món thích hợp, nên trở về Thạch Tháp đổi Ngọc Bài ghi công trạng thành lệnh bài và nghỉ ba ngày. Hắn quyết định tiếp tục lưu lại Thiên Uyên Thành để chờ buổi truyền đạo tại Thiên Nghiễm Điện và xử lý một việc khác. Sau đó, Hàn Lập tới một sơn cốc ngoài thành, mở thông đạo bí mật trong thạch bích và gia nhập cuộc tụ hội của các phi thăng tu sĩ. Khi khoảng mười lăm đến mười sáu tu sĩ đã tề tựu, Văn tu sĩ và Triệu Vô Quy xuất hiện thay Phạm đạo hữu chủ trì. Triệu Vô Quy mở đầu phần trao đổi tâm đắc tu luyện, giới hạn mỗi người được hỏi một vấn đề và treo thưởng Diệt Trần Đan cùng linh dược cho những tin tình báo hữu dụng."},{"chuong":1352,"tieuDe":"Phi Thăng Tu Sĩ","tomTat":"Trong buổi tụ hội của các phi thăng tu sĩ, Hàn Lập dùng một khối vạn năm Huyền Ngọc đổi lấy vài đạo phù quý hiếm, rồi cùng mọi người trao đổi sở ngộ tu luyện. Phần trình bày về đạo luyện phù và Ngân Khoa Linh Phù của hắn khiến Văn tu sĩ cùng Triệu Vô Quy chú ý, nhưng hắn không hỏi về những trở ngại của Phạm Thánh Chân Ma Công vì công pháp này không có tiền lệ tu luyện. Hai tu sĩ Luyện Hư sau đó công bố tình báo cho thấy Thiên Uyên Thành có khả năng lớn bị dị tộc công kích, thậm chí có thể trở thành điểm bùng phát Bách Tộc Đại Chiến. Triệu Vô Quy còn xác nhận phi thăng tu sĩ thường bị giao nhiệm vụ nguy hiểm hơn tu sĩ bản địa, khiến tỷ lệ thương vong của họ đặc biệt cao. Dù nghiêm cấm mọi người tự tiện đào ngũ, Lôi La Chân Nhân đã chuẩn bị những nhiệm vụ nguy hiểm có công huân rất cao để người hoàn thành có thể rời thành hợp pháp trước lúc công thành. Con đường này có xác suất tử vong lên tới năm thành, nhưng có thể giúp giới phi thăng bảo toàn một phần nguyên khí nếu đại chiến bùng nổ. Nhận ra tình thế nghiêm trọng hơn dự kiến, Hàn Lập quyết định phải sớm hoạch định sách lược tự bảo vệ."},{"chuong":1353,"tieuDe":"Linh Trùng Đại Thành","tomTat":"Tại hội nghị, Triệu Vô Quy và Văn tu sĩ giải thích rằng người nhận nhiệm vụ đặc biệt sẽ được xóa nhiệm vụ cũ và cấp đủ Diệt Trần Đan, nhưng số đan này mang cấm chế tự hủy nếu nhiệm vụ thất bại. Sau hội nghị, Huyên tiên tử đánh giá cao thực lực của Hàn Lập và đề nghị liên thủ, song hắn khéo léo từ chối vì còn phải tế luyện Phệ Kim Trùng và muốn giữ kín bí mật. Trở lại Thạch Tháp, Hàn Lập xuất Nguyên Anh tu luyện, dùng ngân sắc hỏa diễm kích phát năm cốt giới cùng đồ án tiểu sơn trên hai bàn tay, đồng thời hiển lộ kim sắc hư ảnh ba đầu sáu tay. Sau khi dự buổi giảng đạo tại Thiên Nghiễm Điện, hắn chứng kiến Trưởng Lão Hội công bố những nhiệm vụ nguy hiểm liên quan Dị Tộc dành riêng cho tu sĩ Hóa Thần. Một nhóm khách bí ẩn sau đó tới động phủ mật đàm với Hàn Lập, khiến hắn suy nghĩ nhiều ngày trước khi đưa ra quyết định. Bốn tháng sau, khoảng sáu đến bảy nghìn Phệ Kim Trùng đã được tế luyện thuần thục và đạt đại thành. Hàn Lập thu dọn động phủ, bí mật nhận một nhiệm vụ rồi rời Thiên Uyên Thành, trong khi nhiều tu sĩ Hóa Thần danh tiếng khác cũng biến mất khỏi thành theo cách tương tự."}];
